async function run(task, tools, context) {
  const trace = [];

  // Helper to safely call tools with up to 2 retries on transient errors
  async function callTool(name, args) {
    let retries = 0;
    while (true) {
      try {
        const result = await tools.call(name, args);
        return result;
      } catch (err) {
        const isTransient = err && (err.code === 'UPSTREAM_503' || err.code === 'TIMEOUT' || err.name === 'ToolError');
        if (isTransient && retries < 2) {
          retries++;
          trace.push(`Retry ${retries} for tool ${name}`);
          continue;
        }
        throw err;
      }
    }
  }

  // 1. Validate task inputs
  const inputs = task?.inputs || {};
  const city = typeof inputs.city === 'string' ? inputs.city.trim() : '';
  const checkin = typeof inputs.checkin === 'string' ? inputs.checkin.trim() : '';
  const nights = Number(inputs.nights);
  const budget = Number(inputs.budget);

  // Date validation simple check (YYYY-MM-DD)
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

  if (!city || !checkin || !dateRegex.test(checkin) || isNaN(nights) || nights <= 0 || !Number.isInteger(nights) || isNaN(budget) || budget <= 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: 'Please provide valid inputs: city (string), checkin (YYYY-MM-DD format), positive integer nights, and positive budget in INR.'
      },
      trace
    };
  }

  trace.push(`Planning trip to ${city} for ${nights} nights starting ${checkin} with budget ${budget} INR`);

  // Helper for coercing numbers (e.g., "4,500" -> 4500)
  function parseNumber(val) {
    if (val === null || val === undefined) return null;
    if (typeof val === 'number') return isNaN(val) ? null : val;
    if (typeof val === 'string') {
      const clean = val.replace(/,/g, '').trim();
      const num = parseFloat(clean);
      return isNaN(num) ? null : num;
    }
    return null;
  }

  // Fetch hotels and attractions in parallel
  let hotelsRaw = [];
  let attractionsRaw = [];

  try {
    const [hRes, aRes] = await Promise.all([
      callTool('search_hotels', { city, checkin, nights }),
      callTool('list_attractions', { city })
    ]);
    hotelsRaw = Array.isArray(hRes) ? hRes : [];
    attractionsRaw = Array.isArray(aRes) ? aRes : [];
  } catch (err) {
    trace.push(`Tool failure: ${err.message || err}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Failed to fetch hotels or attractions' },
      trace
    };
  }

  // Process and sanitize hotels
  const hotels = [];
  for (const h of hotelsRaw) {
    if (!h || typeof h !== 'object') continue;
    const id = h.id ? String(h.id) : null;
    const pricePerNight = parseNumber(h.price_per_night);
    if (id && pricePerNight !== null && pricePerNight >= 0) {
      hotels.push({
        id,
        name: h.name || 'Hotel',
        price_per_night: pricePerNight,
        total_cost: pricePerNight * nights
      });
    }
  }

  // Process and sanitize attractions
  const attractions = [];
  for (const a of attractionsRaw) {
    if (!a || typeof a !== 'object') continue;
    const id = a.id ? String(a.id) : null;
    let entryFee = parseNumber(a.entry_fee);
    if (entryFee === null && (a.entry_fee === null || a.entry_fee === undefined)) {
      entryFee = 0; // null entry_fee means free per tool description
    }
    if (id && entryFee !== null && entryFee >= 0) {
      attractions.push({
        id,
        name: a.name || 'Attraction',
        cost: entryFee
      });
    }
  }

  trace.push(`Found ${hotels.length} valid hotels and ${attractions.length} valid attractions`);

  // Require at least 1 hotel and 2 distinct attractions
  if (hotels.length === 0 || attractions.length < 2) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Insufficient options available in the city (need at least 1 hotel and 2 distinct attractions).' },
      trace
    };
  }

  // Find a combination within budget
  // We pick the best option or any valid combination fitting within budget.
  let bestPlan = null;
  let minCost = Infinity;

  for (const hotel of hotels) {
    for (let i = 0; i < attractions.length; i++) {
      for (let j = i + 1; j < attractions.length; j++) {
        const attr1 = attractions[i];
        const attr2 = attractions[j];

        const total = hotel.total_cost + attr1.cost + attr2.cost;
        if (total <= budget) {
          // If multiple options exist, we can select the one that fits within budget (e.g. lowest cost or just first found)
          if (total < minCost) {
            minCost = total;
            bestPlan = {
              plan: [
                { kind: 'hotel', id: hotel.id, cost: hotel.total_cost },
                { kind: 'attraction', id: attr1.id, cost: attr1.cost },
                { kind: 'attraction', id: attr2.id, cost: attr2.cost }
              ],
              total_cost: total
            };
          }
        }
      }
    }
  }

  if (!bestPlan) {
    trace.push('No combination found within budget');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No combination of 1 hotel and 2 attractions fits within the specified budget.' },
      trace
    };
  }

  trace.push(`Successfully selected plan with total cost ${bestPlan.total_cost} INR`);

  return {
    status: 'success',
    answer: bestPlan,
    success_indicators: { total_cost: bestPlan.total_cost },
    trace
  };
}
