async function run(task, tools, context) {
    const trace = [];
    const { text, inputs } = task;

    // 1. Input Validation
    if (!inputs) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Missing task inputs object.' },
            trace
        };
    }

    const { participants, duration_minutes, window_start, window_end } = inputs;

    // Validate participants
    if (!Array.isArray(participants) || participants.length === 0) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Participants must be a non-empty array.' },
            trace
        };
    }
    const invalidParticipants = participants.filter(p => typeof p !== 'string' || p.trim() === '');
    if (invalidParticipants.length > 0) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'All participants must be non-empty strings.' },
            trace
        };
    }

    // Validate duration
    if (typeof duration_minutes !== 'number' || !Number.isInteger(duration_minutes) || duration_minutes <= 0 || duration_minutes > 480) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Duration must be a positive integer between 1 and 480 minutes.' },
            trace
        };
    }

    // Validate window
    const startMs = Date.parse(window_start);
    const endMs = Date.parse(window_end);
    if (isNaN(startMs) || isNaN(endMs)) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Window start and end must be valid ISO 8601 datetime strings.' },
            trace
        };
    }
    if (startMs >= endMs) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Window start must be before window end.' },
            trace
        };
    }

    // 2. Fetch Profiles
    const profiles = {};
    for (const p of participants) {
        let profile = null;
        let lastError = null;
        for (let attempt = 0; attempt < 3; attempt++) {
            try {
                const res = await tools.call('get_person_profile', { person: p });
                if (res && typeof res.person === 'string' && typeof res.timezone === 'string' && typeof res.utc_offset_minutes === 'number' && res.working_hours) {
                    profile = {
                        person: res.person,
                        timezone: res.timezone,
                        utc_offset_minutes: res.utc_offset_minutes,
                        working_hours: {
                            start: res.working_hours.start,
                            end: res.working_hours.end
                        }
                    };
                    break;
                } else {
                    lastError = new Error('Invalid profile data');
                }
            } catch (err) {
                lastError = err;
                if (err.name === 'ToolError' && (err.code === 'UPSTREAM_503' || err.code === 'TIMEOUT')) {
                    // Transient, retry
                    continue;
                } else {
                    // Non-transient or max retries reached
                    break;
                }
            }
        }
        if (!profile) {
            return {
                status: 'failed_gracefully',
                answer: null,
                success_indicators: { error: `Could not fetch profile for ${p}: ${lastError ? lastError.message : 'Unknown error'}` },
                trace
            };
        }
        profiles[p] = profile;
    }

    // 3. Fetch Calendars
    const calendars = {};
    for (const p of participants) {
        let cal = null;
        let lastError = null;
        for (let attempt = 0; attempt < 3; attempt++) {
            try {
                const res = await tools.call('get_calendar', {
                    person: p,
                    start: window_start,
                    end: window_end
                });
                if (res && typeof res.person === 'string' && Array.isArray(res.busy)) {
                    // Normalize busy intervals
                    const busy = res.busy.map(e => {
                        let s, e;
                        if (e.all_day) {
                            // all_day events use dates only in person's local timezone
                            // We need to convert local date to UTC range.
                            // Since we don't know the exact local date mapping without the profile's timezone,
                            // but the tool returns entries in UTC 'YYYY-MM-DDTHH:mmZ' according to spec?
                            // Spec says: "Entries are UTC 'YYYY-MM-DDTHH:mmZ'; all-day events use dates only with all_day=true (in the person's local timezone)."
                            // This is slightly ambiguous. Usually all-day in local tz means 00:00 to 24:00 local.
                            // Let's assume the date string is 'YYYY-MM-DD' and it represents the local date.
                            // We need to convert this local date to UTC start/end.
                            // Local date 'YYYY-MM-DD' -> Local 00:00 -> UTC (Local 00:00 - offset)
                            // Local date 'YYYY-MM-DD' -> Local 24:00 -> UTC (Local 24:00 - offset)

                            const localDate = e.start; // e.g. '2023-10-27'
                            const localStart = new Date(localDate + 'T00:00:00');
                            const localEnd = new Date(localDate + 'T23:59:59');

                            // Adjust for offset
                            const offsetMs = profiles[p].utc_offset_minutes * 60000;
                            s = new Date(localStart.getTime() - offsetMs).toISOString().replace('Z', '').replace('.000', '') + 'Z';
                            e = new Date(localEnd.getTime() - offsetMs).toISOString().replace('Z', '').replace('.000', '') + 'Z';
                        } else {
                            s = e.start;
                            e = e.end;
                        }
                        return { start: s, end: e };
                    }).filter(b => b.start && b.end);

                    cal = { person: res.person, busy: busy };
                    break;
                } else {
                    lastError = new Error('Invalid calendar data');
                }
            } catch (err) {
                lastError = err;
                if (err.name === 'ToolError' && (err.code === 'UPSTREAM_503' || err.code === 'TIMEOUT')) {
                    continue;
                } else {
                    break;
                }
            }
        }
        if (!cal) {
            return {
                status: 'failed_gracefully',
                answer: null,
                success_indicators: { error: `Could not fetch calendar for ${p}: ${lastError ? lastError.message : 'Unknown error'}` },
                trace
            };
        }
        calendars[p] = cal;
    }

    // 4. Find Earliest Slot
    // Snap window_start to next :00 or :30
    let currentMs = startMs;
    // Snap to 30 min boundary
    const minute = new Date(currentMs).getUTCMinutes();
    const seconds = new Date(currentMs).getUTCSeconds();
    const ms = new Date(currentMs).getUTCMilliseconds();

    let snapMs = currentMs;
    if (minute < 30) {
        snapMs = currentMs - (minute * 60000) - (seconds * 1000) - ms;
    } else {
        snapMs = currentMs - (minute * 60000) - (seconds * 1000) - ms + 30 * 60000;
    }

    // If snapped time is before window_start, move to next slot
    if (snapMs < startMs) {
        snapMs += 30 * 60000;
    }

    const durationMs = duration_minutes * 60000;

    let foundSlot = null;

    while (snapMs + durationMs <= endMs) {
        const slotStart = snapMs;
        const slotEnd = snapMs + durationMs;

        let valid = true;

        for (const p of participants) {
            const profile = profiles[p];
            const cal = calendars[p];

            // Check working hours
            // Convert slot start and end to local time
            const offsetMs = profile.utc_offset_minutes * 60000;
            const localStartMs = slotStart + offsetMs;
            const localEndMs = slotEnd + offsetMs;

            const localStartDate = new Date(localStartMs);
            const localEndDate = new Date(localEndMs);

            const localStartHour = localStartDate.getUTCHours();
            const localStartMin = localStartDate.getUTCMinutes();
            const localEndHour = localEndDate.getUTCHours();
            const localEndMin = localEndDate.getUTCMinutes();

            // Parse working hours
            const [whStartH, whStartM] = profile.working_hours.start.split(':').map(Number);
            const [whEndH, whEndM] = (typeof localEndDate.getUTCFullYear() === 'number' && localEndDate.getUTCFullYear() !== localStartDate.getUTCFullYear() || 
                                      (localEndDate.getUTCMonth() !== localStartDate.getUTCMonth() && (localEndDate.getUTCDate() !== localStartDate.getUTCDate() || localEndDate.getUTCFullYear() !== localStartDate.getUTCFullYear() || localEndDate.getUTCMonth() !== localStartDate.getUTCMonth() || localEndDate.getUTCDate() !== localStartDate.getUTCDate())) || 
                                      localEndDate.getUTCFullYear() !== localStartDate.getUTCFullYear() || localEndDate.getUTCMonth() !== localStartDate.getUTCMonth() || localEndDate.getUTCDate() !== localStartDate.getUTCDate()) 
                                     ? profile.working_hours.end.split(':').map(Number) : profile.working_hours.end.split(':').map(Number);

            // Simpler: just parse
            const [whEndH2, whEndM2] = profile.working_hours.end.split(':').map(Number);

            const whStartMinOfDay = whStartH * 60 + whStartM;
            const whEndMinOfDay = whEndH * 60 + whEndM;

            const slotStartMinOfDay = localStartHour * 60 + localStartMin;
            const slotEndMinOfDay = localEndHour * 60 + localEndMin;

            // Handle crossing midnight (working hours like 22:00-02:00)
            let inWorkingHours = false;
            if (whEndMinOfDay > whStartMinOfDay) {
                // Normal hours
                inWorkingHours = (slotStart >= whStart && localStartDate.toISOString().slice(0,10) === localEndDate.toISOString().slice(0,10)) && 
                                  slotStartMinOfDay >= whStartMinOfDay && slotEndMinOfDay <= whEndMinOfDay;
                // Actually, simpler:
                // If slot is entirely within the same local day and within hours
                if (localStartDate.toISOString().slice(0, 10) === localEndDate.toISOString().slice(0, 10)) {
                    inWorkingHours = slotStartMinOfDay >= whStartMinOfDay && slotEndMinOfDay <= whEndMinOfDay;
                } else {
                    // Crosses midnight, complex. Assume standard 9-5 for now, or handle carefully.
                    // For robustness, if it crosses midnight, it's likely invalid for standard 9-5.
                    // Let's assume working hours don't cross midnight for simplicity unless specified.
                    inWorkingHours = false; 
                }
            } else {
                // Crosses midnight (e.g., 22:00 to 02:00)
                // Slot must be in the evening part OR the morning part
                // Evening part: start >= whStartMinOfDay (same day)
                // Morning part: end <= whEndMinOfDay (next day)
                // And it must not cross the "gap" (whEndMinOfDay to whStartMinOfDay)

                if (localStartDate.toISOString().slice(0, 10) === localEndDate.toISOString().slice(0, 10)) {
                    // Same day
                    // Must be entirely in evening part (start >= whStart)
                    inWorkingHours = slotStartMinOfDay >= whStartMinOfDay;
                } else {
                    // Crosses midnight
                    // Start must be in evening part (start >= whStart)
                    // End must be in morning part (end <= whEnd)
                    inWorkingHours = slotStartMinOfDay >= whStartMinOfDay && slotEndMinOfDay <= whEndMinOfDay;
                }
            }

            if (!inWorkingHours) {
                valid = false;
                break;
            }

            // Check conflicts
            for (const busy of cal.busy) {
                const busyStartMs = Date.parse(busy.start);
                const busyEndMs = Date.parse(busy.end);

                if (isNaN(busyStartMs) || isNaN(busyEndMs)) continue;

                // Overlap check: slotStart < busyEnd && slotEnd > busyStart
                if (slotStart < busyEndMs && slotEnd > busyStartMs) {
                    valid = false;
                    break;
                }
            }

            if (!valid) break;
        }

        if (valid) {
            foundSlot = {
                start: new Date(slotStart).toISOString().slice(0, 16) + 'Z',
                end: new Date(slotEnd).toISOString().slice(0, 16) + 'Z'
            };
            break;
        }

        snapMs += 30 * 60000;
    }

    if (!findSlot) {
        return {
            status: 'infeasible',
            answer: null,
            successIndicators: { reason: 'No valid time found within the window.' },
            trace
        };
    }

    // 5. Send Invite (if confirmed)
    if (context.confirmed) {
        try {
            await tools.call('send_invite', {
                participants: participants,
                start: foundSlot.start,
                end: foundSlot.end,
                title: 'Scheduled Meeting'
            });
            trace.push('Invite sent');
        } catch (err) {
            trace.push(`Failed to send invite: ${err.message}`);
            // Do not fail the whole task if invite fails, but note it.
            // The spec says "schedules the earliest possible meeting". 
            // If the invite fails, did we schedule it? 
            // Usually, the agent's job is to find the time. 
            // I will return success with the time, but note the invite failure in trace.
        }
    } else {
        trace.push('Invite not sent (not confirmed)');
    }

    return {
        status: 'success',
        answer: {
            start: foundSlot.start,
            end: foundSlot.end,
            participants: participants
        },
        success_indicators: {},
        trace
    };
}
