async function run(task, tools, context) {
  const { city, count, budget } = task.inputs;
  const trace = [];

  if (!city || typeof count !== 'number' || typeof budget !== 'number') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide city, count, and budget.' },
      trace: ['Missing required inputs']
    };
  }

  let restaurants = [];
  try {
    let retries = 2;
    while (retries >= 0) {
      try {
        restaurants = await tools.call('search_restaurants', { city, veg_only: true });
        break;
      } catch (err) {
        if (retries === 0 || err.code === 'NOT_FOUND') throw err;
        retries--;
      }
    }
  } catch (err) {
    if (err.code === 'NOT_FOUND' || err.code === 'INVALID_ARGS') {
      return {
        status: 'infeasible',
        answer: null,
        success_indicators: {},
        trace: [`Tool error: ${err.message}`]
      };
    }
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [`Tool call failed: ${err.message}`]
    };
  }

  if (!Array.isArray(restaurants)) {
    restaurants = [];
  }

  // Filter valid veg restaurants and ensure cost is a number
  const vegRestaurants = restaurants.filter(r => {
    if (!r || r.veg !== true) return false;
    let cost = r.avg_cost_for_two;
    if (typeof cost === 'string') {
      cost = Number(cost.replace(/,/g, ''));
    }
    return typeof cost === 'number' && !isNaN(cost);
  }).map(r => ({
    ...r,
    avg_cost_for_two: typeof r.avg_cost_for_two === 'string' 
      ? Number(r.avg_cost_for_two.replace(/,/g, '')) 
      : r.avg_cost_for_two
  }));

  trace.push(`Found ${vegRestaurants.length} veg restaurants in ${city}`);

  if (vegRestaurants.length < count) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: ['Not enough vegetarian restaurants available']
    };
  }

  // Sort by cost ascending to maximize chances of fitting in budget
  vegRestaurants.sort((a, b) => a.avg_cost_for_two - b.avg_cost_for_two);

  // Pick the first `count` restaurants
  const selected = vegRestaurants.slice(0, count);
  const total_cost = selected.reduce((sum, r) => sum + r.avg_cost_for_two, 0);

  if (total_cost > budget) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: [`Cheapest ${count} restaurants cost ${total_cost}, which exceeds budget ${budget}`]
    };
  }

  const plan = selected.map(r => ({
    kind: 'restaurant',
    id: r.id,
    cost: r.avg_cost_for_two
  }));

  return {
    status: 'success',
    answer: {
      plan,
      total_cost
    },
    success_indicators: {},
    trace
  };
}
