async function run(task, tools, context) {
  const trace = [];
  const { city, days } = task.inputs || {};

  if (!city || typeof city !== 'string') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid city name in India.' },
      trace: ['Missing or invalid city input.']
    };
  }

  const numDays = Number(days);
  if (!numDays || numDays < 1 || numDays > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide the number of days between 1 and 16.' },
      trace: ['Missing or invalid days input (must be 1..16).']
    };
  }

  async function callToolWithRetry(name, args, retries = 2) {
    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        if (attempt === retries || (err && err.code === 'INVALID_ARGS')) {
          throw err;
        }
        trace.push(`Tool ${name} failed (attempt ${attempt + 1}), retrying...`);
      }
    }
  }

  // Step 1: Geocode city with country_code 'IN'
  let geoResults;
  try {
    trace.push(`Geocoding city: ${city}`);
    geoResults = await callToolWithRetry('geocode_city', { city, country_code: 'IN' });
  } catch (err) {
    trace.push(`Geocode failed: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    // Try without country_code restriction just in case
    try {
      trace.push(`Geocoding city without country restriction: ${city}`);
      geoResults = await callToolWithRetry('geocode_city', { city });
    } catch (err) {
      // ignore
    }
  }

  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: `Could not find coordinates for city: ${city}` },
      trace
    };
  }

  const location = geoResults[0];
  if (typeof location.latitude !== 'number' || typeof location.longitude !== 'number') {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { reason: 'Invalid location data returned from geocode.' },
      trace
    };
  }

  // Step 2: Fetch weather forecast
  let forecast;
  try {
    trace.push(`Fetching weather forecast for lat=${location.latitude}, lon=${location.longitude}, days=${numDays}`);
    forecast = await callToolWithRetry('weather_forecast', {
      latitude: location.latitude,
      longitude: location.longitude,
      days: numDays
    });
  } catch (err) {
    trace.push(`Weather forecast failed: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  if (!forecast || !Array.isArray(forecast.daily) || forecast.daily.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No daily weather forecast data available.' },
      trace
    };
  }

  const dailyData = forecast.daily.slice(0, numDays);
  let sumTempMaxC = 0;
  let count = 0;

  for (const day of dailyData) {
    let tempMaxC = day.temp_max_c;
    if (typeof tempMaxC === 'string') {
      tempMaxC = parseFloat(tempMaxC.replace(/,/g, ''));
    }
    if (typeof tempMaxC === 'number' && !isNaN(tempMaxC)) {
      sumTempMaxC += tempMaxC;
      count++;
    }
  }

  if (count === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No valid max temperature values found in forecast.' },
      trace
    };
  }

  const avgTempC = sumTempMaxC / count;
  // Convert Celsius to Fahrenheit: F = C * 9/5 + 32
  const avgTempF = avgTempC * (9 / 5) + 32;
  const roundedValue = Math.round(avgTempF * 100) / 100;

  trace.push(`Calculated average max temp: ${roundedValue} °F`);

  return {
    status: 'success',
    answer: {
      value: roundedValue,
      unit: 'F'
    },
    success_indicators: { city, days: numDays, average_fahrenheit: roundedValue },
    trace
  };
}
