async function run(task, tools, context) {
  const trace = [];
  const { city_a, city_b, days } = task.inputs;

  if (!city_a || !city_b || !days) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide city_a, city_b, and days.' },
      trace: ['Missing required inputs']
    };
  }

  async function callToolWithRetry(name, args, retries = 2) {
    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        trace.push(`Tool ${name} failed: ${err.message} (attempt ${attempt + 1})`);
        if (err.code === 'NOT_FOUND' || err.code === 'INVALID_ARGS') {
          throw err;
        }
        if (attempt === retries) throw err;
      }
    }
  }

  async function getCityCoords(cityName) {
    const results = await callToolWithRetry('geocode_city', { city: cityName, country_code: 'IN' });
    if (!Array.isArray(results) || results.length === 0) {
      const fallback = await callToolWithRetry('geocode_city', { city: cityName });
      if (!Array.isArray(fallback) || fallback.length === 0) {
        throw new Error(`Could not find coordinates for city: ${cityName}`);
      }
      return fallback[0];
    }
    return results[0];
  }

  let locA, locB;
  try {
    locA = await getCityCoords(city_a);
    locB = await getCityCoords(city_b);
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  let forecastA, forecastB;
  try {
    forecastA = await callToolWithRetry('weather_forecast', {
      latitude: locA.latitude,
      longitude: locA.longitude,
      days: days
    });
    forecastB = await callToolWithRetry('weather_forecast', {
      latitude: locB.latitude,
      longitude: locB.longitude,
      days: days
    });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  if (!forecastA?.daily || !forecastB?.daily || forecastA.daily.length === 0 || forecastB.daily.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Empty forecast data returned' },
      trace
    };
  }

  const computeAvgMax = (daily) => {
    let sum = 0;
    let count = 0;
    for (const d of daily) {
      let t = d.temp_max_c;
      if (typeof t === 'string') {
        t = parseFloat(t.replace(',', ''));
      }
      if (typeof t === 'number' && !isNaN(t)) {
        sum += t;
        count++;
      }
    }
    if (count === 0) throw new Error('No valid temperature data available');
    return sum / count;
  };

  let avgA, avgB;
  try {
    avgA = computeAvgMax(forecastA.daily);
    avgB = computeAvgMax(forecastB.daily);
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  const diff = avgA - avgB;
  trace.push(`Computed average max temp for ${city_a}: ${avgA}, ${city_b}: ${avgB}, diff: ${diff}`);

  return {
    status: 'success',
    answer: {
      value: Number(diff.toFixed(2)),
      unit: 'Celsius'
    },
    success_indicators: {
      city_a_avg_max: avgA,
      city_b_avg_max: avgB
    },
    trace
  };
}
