async function run(task, tools, context) {
  const trace = [];
  const successIndicators = {};

  // ---------- Validate task inputs ----------
  const { city, days } = task.inputs || {};

  if (typeof city !== 'string' || city.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a non‑empty city name.' },
      trace
    };
  }

  const daysNum = Number(days);
  if (!Number.isInteger(daysNum) || daysNum < 1 || daysNum > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'The "days" value must be an integer between 1 and 16.' },
      trace
    };
  }

  // ---------- Helper: safe tool call with retries ----------
  async function safeCall(name, args) {
    const maxAttempts = 3; // initial try + 2 retries
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        const result = await tools.call(name, args);
        trace.push(`Tool "${name}" succeeded on attempt ${attempt}`);
        return result;
      } catch (err) {
        if (err && err.name === 'ToolError' && ['UPSTREAM_503', 'TIMEOUT'].includes(err.code)) {
          if (attempt === maxAttempts) {
            trace.push(`Tool "${name}" failed after ${maxAttempts} attempts: ${err.code}`);
            throw err;
          }
          trace.push(`Transient error "${err.code}" on tool "${name}", retrying (${attempt}/${maxAttempts})`);
          continue;
        } else {
          trace.push(`Tool "${name}" failed with non‑transient error: ${err.code || err.message}`);
          throw err;
        }
      }
    }
  }

  // ---------- Resolve city to coordinates ----------
  let geoResults;
  try {
    geoResults = await safeCall('geocode_city', { city, country_code: 'IN' });
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Geocoding failed: ${e.code || e.message}` },
      trace
    };
  }

  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { error: 'City not found in India.' },
      trace
    };
  }

  const { latitude, longitude } = geoResults[0];
  if (typeof latitude !== 'number' || typeof longitude !== 'number') {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Geocode result missing valid coordinates.' },
      trace
    };
  }

  // ---------- Fetch weather forecast ----------
  let forecast;
  try {
    forecast = await safeCall('weather_forecast', { latitude, longitude, days: daysNum });
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Weather forecast failed: ${e.code || e.message}` },
      trace
    };
  }

  // ---------- Validate forecast structure ----------
  if (
    typeof forecast !== 'object' ||
    !Array.isArray(forecast.daily) ||
    forecast.daily.length < daysNum
  ) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Forecast data is incomplete or malformed.' },
      trace
    };
  }

  // ---------- Compute average daily max temperature in Fahrenheit ----------
  let sumF = 0;
  for (let i = 0; i < daysNum; i++) {
    const day = forecast.daily[i];
    if (
      typeof day !== 'object' ||
      typeof day.temp_max_c !== 'number'
    ) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Missing or invalid temp_max_c for day ${i + 1}.` },
        trace
      };
    }
    const tempC = day.temp_max_c;
    const tempF = tempC * 9 / 5 + 32;
    sumF += tempF;
  }
  const avgF = sumF / daysNum;

  // ---------- Return success ----------
  return {
    status: 'success',
    answer: { value: avgF, unit: 'F' },
    success_indicators: { city, days: daysNum, avgF },
    trace
  };
}
