 * (city_a minus city_b) in Celsius over the next N days.
 *
 * Expected task.inputs:
 *   - city_a: string (Indian city)
 *   - city_b: string (Indian city)
 *   - days: integer (1..16)
 *
 * Answer schema on success:
 *   { value: number, unit: "Celsius" }
 */
async function run(task, tools, context) {
  const trace = [];

  // ---------- Helper utilities ----------
  const isInteger = (n) => Number.isInteger(n);
  const clamp = (min, max, v) => Math.max(min, Math.min(max, v));

  // Simple retry wrapper for transient tool errors
  async function callTool(name, args, maxRetries = 2) {
    let attempt = 0;
    while (true) {
      try {
        const result = await tools.call(name, args);
        return result;
      } catch (e) {
        if (e.name !== 'ToolError' || !['UPSTREAM_503', 'TIMEOUT'].includes(e.code) || attempt >= maxRetries) {
          throw e; // non‑transient or out of retries
        }
        attempt++;
        trace.push(`Retry ${attempt} for tool ${name} due to transient error ${e.code}`);
      }
    }
  }

  // Validate task inputs
  const { city_a, city_b, days } = task.inputs || {};
  if (typeof city_a !== 'string' || city_a.trim() === '' ||
      typeof city_b !== 'string' || city_b.trim() === '' ||
      !isInteger(days) || days < 1 || days > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: 'Please provide valid inputs: city_a (string), city_b (string), days (integer 1‑16).'
      },
      trace
    };
  }

  // ---------- Resolve cities ----------
  async function resolveCity(name) {
    const geo = await callTool('geocode_city', { city: name, country_code: 'IN' });
    if (!Array.isArray(geo) || geo.length === 0) {
      throw new Error(`Geocode returned no results for "${name}"`);
    }
    const { latitude, longitude } = geo[0];
    if (typeof latitude !== 'number' || typeof longitude !== 'number') {
      throw new Error(`Invalid geocode data for "${name}"`);
    }
    return { latitude, longitude };
  }

  let coordA, coordB;
  try {
    coordA = await resolveCity(city_a);
    trace.push(`Resolved ${city_a} to (${coordA.latitude}, ${coordA.longitude})`);
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Could not resolve city_a: ${e.message}` },
      trace
    };
  }

  try {
    coordB = await resolveCity(city_b);
    trace.push(`Resolved ${city_b} to (${coordB.latitude}, ${coordB.longitude})`);
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Could not resolve city_b: ${e.message}` },
      trace
    };
  }

  // ---------- Fetch forecasts ----------
  async function fetchForecast(coord) {
    const forecast = await callTool('weather_forecast', {
      latitude: coord.latitude,
      longitude: coord.longitude,
      days
    });
    if (!forecast || typeof forecast !== 'object' || !Array.isArray(forecast.daily)) {
      throw new Error('Malformed forecast response');
    }
    if (forecast.daily.length < days) {
      throw new Error(`Forecast returned only ${forecast.daily.length} days, expected ${days}`);
    }
    // Validate each day's structure
    const temps = forecast.daily.slice(0, days).map((d, idx) => {
      if (typeof d.temp_max_c !== 'number') {
        // attempt coercion from string like "23,5"
        let num = Number(d.temp_max_c?.toString().replace(',', '.'));
        if (Number.isNaN(num)) {
          throw new Error(`Invalid temp_max_c on day ${idx + 1}`);
        }
        return num;
      }
      return d.temp_max_c;
    });
    return temps;
  }

  let tempsA, tempsB;
  try {
    tempsA = await fetchForecast(coordA);
    trace.push(`Fetched forecast for ${city_a}`);
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Forecast error for city_a: ${e.message}` },
      trace
    };
  }

  try {
    tempsB = await fetchForecast(coordB);
    trace.push(`Fetched forecast for ${city_b}`);
  } catch (e) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Forecast error for city_b: ${e.message}` },
      trace
    };
  }

  // ---------- Compute average max temperatures ----------
  const avg = (arr) => arr.reduce((s, v) => s + v, 0) / arr.length;
  const avgA = avg(tempsA);
  const avgB = avg(tempsB);
  const diff = avgA - avgB;

  // ---------- Return result ----------
  return {
    status: 'success',
    answer: {
      value: Number(diff.toFixed(2)), // round to 2 decimal places
      unit: 'Celsius'
    },
    success_indicators: {
      average_max_a: Number(avgA.toFixed(2)),
      average_max_b: Number(avgB.toFixed(2)),
      days_considered: days
    },
    trace
  };
}
