            trace: ['Missing or invalid inputs']
        };
    }

    async function callToolWithRetry(name, args, retries = 2) {
        for (let attempt = 0; attempt <= retries; attempt++) {
            try {
                return await tools.call(name, args);
            } catch (err) {
                trace.push(`Tool ${name} failed (attempt ${attempt + 1}): ${err.message}`);
                if (err.name === 'ToolError' && (err.code === 'INVALID_ARGS' || err.code === 'NOT_FOUND')) {
                    throw err;
                }
                if (attempt === retries) throw err;
            }
        }
    }

    let hotels = [];
    try {
        trace.push(`Searching hotels in ${city}`);
        hotels = await callToolWithRetry('search_hotels', { city });
    } catch (err) {
        return {
            status: 'failed_gracefully',
            answer: null,
            success_indicators: { error: err.message },
            trace
        };
    }

    if (!Array.isArray(hotels) || hotels.length === 0) {
        return {
            status: 'infeasible',
            answer: null,
            success_indicators: { reason: 'No hotels found for the given city' },
            trace
        };
    }

    // Filter hotels: must have rating >= min_rating (hotels without rating excluded)
    const validHotels = hotels.filter(h => {
        if (typeof h.rating !== 'number') return false;
        return h.rating >= minRating;
    });

    if (validHotels.length === 0) {
        return {
            status: 'infeasible',
            answer: null,
            success_indicators: { reason: 'No hotels found matching the minimum rating' },
            trace
        };
    }

    // Calculate average price in INR
    let totalPriceInr = 0;
    let count = 0;
    for (const h of validHotels) {
        let price = h.price_per_night;
        if (typeof price === 'string') {
            price = parseFloat(price.replace(/,/g, ''));
        }
        if (typeof price === 'number' && !isNaN(price)) {
            totalPriceInr += price;
            count++;
        }
    }

    if (count === 0) {
        return {
            status: 'infeasible',
            answer: null,
            success_indicators: { reason: 'No valid prices found for filtered hotels' },
            trace
        };
    }

    const avgPriceInr = totalPriceInr / count;
    trace.push(`Average price in INR: ${avgPriceInr} across ${count} hotels`);

    // Convert currency to USD
    let conversion;
    try {
        trace.push('Converting INR to USD');
        conversion = await callToolWithRetry('convert_currency', {
            amount: avgPriceInr,
            from: 'INR',
            to: 'USD'
        });
    } catch (err) {
        return {
            status: 'failed_gracefully',
            answer: null,
            success_indicators: { error: err.message },
            trace
        };
    }

    let convertedValue = conversion.converted;
    if (typeof convertedValue === 'string') {
        convertedValue = parseFloat(convertedValue.replace(/,/g, ''));
    }

    if (typeof convertedValue !== 'number' || isNaN(convertedValue)) {
        return {
            status: 'failed_gracefully',
            answer: null,
            success_indicators: { reason: 'Invalid currency conversion output' },
            trace
        };
    }

    return {
        status: 'success',
        answer: {
            value: Number(convertedValue.toFixed(2)),
            unit: 'USD'
        },
        success_indicators: { hotels_counted: count },
        trace
    };
}
