async function run(task, tools, context) {
  const trace = [];

  // Helper: call tool with retry for transient errors
  async function callToolWithRetry(name, args) {
    let attempts = 0;
    while (attempts < 3) {
      attempts++;
      try {
        const result = await tools.call(name, args);
        return result;
      } catch (err) {
        const isTransient = err && (err.code === 'UPSTREAM_503' || err.code === 'TIMEOUT' || err.name === 'TimeoutError');
        if (isTransient && attempts < 3) {
          trace.push(`Transient error calling ${name} on attempt ${attempts}: ${err.message}. Retrying...`);
          continue;
        }
        throw err;
      }
    }
  }

  // Parse and validate inputs
  const inputs = task.inputs || {};
  let city = inputs.city;
  let minRating = inputs.min_rating;

  if (typeof city !== 'string' || !city.trim()) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid Indian city name.' },
      trace: ['Invalid or missing city parameter.']
    };
  }
  city = city.trim();

  if (typeof minRating !== 'number' || isNaN(minRating)) {
    // Attempt coercion if numeric string
    const parsed = Number(minRating);
    if (!isNaN(parsed) && minRating !== null && minRating !== undefined && minRating !== '') {
      minRating = parsed;
    } else {
      return {
        status: 'needs_clarification',
        answer: null,
        success_indicators: { question: 'Please provide a valid minimum rating number.' },
        trace: ['Invalid or missing min_rating parameter.']
      };
    }
  }

  // Optional check: verify city is in India via geocode_city if desired, but search_hotels operates directly on city string.
  // Search hotels in the specified city
  let hotelList;
  try {
    hotelList = await callToolWithRetry('search_hotels', { city: city });
    trace.push(`Successfully retrieved hotels for ${city}`);
  } catch (err) {
    trace.push(`Error calling search_hotels: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: trace
    };
  }

  if (!Array.isArray(hotelList) || hotelList.length === 0) {
    trace.push(`No hotels found for city ${city}`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: trace
    };
  }

  // Filter and parse prices
  const validPricesINR = [];

  for (const item of hotelList) {
    if (!item || typeof item !== 'object') continue;

    // Check rating: must be present and >= minRating (hotels without rating are excluded)
    let rating = item.rating;
    if (rating === undefined || rating === null || rating === '') {
      continue;
    }
    rating = Number(rating);
    if (isNaN(rating) || rating < minRating) {
      continue;
    }

    // Parse price_per_night
    let rawPrice = item.price_per_night;
    if (rawPrice === undefined || rawPrice === null) continue;

    let priceNum = 0;
    if (typeof rawPrice === 'number') {
      priceNum = rawPrice;
    } else if (typeof rawPrice === 'string') {
      // Clean commas, spaces, currency symbols
      const cleaned = rawPrice.replace(/,/g, '').replace(/[^0-9.]/g, '');
      priceNum = parseFloat(cleaned);
    }

    if (!isNaN(priceNum) && priceNum > 0) {
      validPricesINR.push(priceNum);
    }
  }

  if (validPricesINR.length === 0) {
    trace.push(`No hotels matching rating >= ${minRating} with valid price found.`);
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: trace
    };
  }

  // Calculate average price in INR
  const sumINR = validPricesINR.reduce((acc, curr) => acc + curr, 0);
  const avgINR = sumINR / validPricesINR.length;
  trace.push(`Found ${validPricesINR.length} matching hotels. Average nightly price: ${avgINR} INR`);

  // Convert INR to USD
  let conversionResult;
  try {
    conversionResult = await callToolWithRetry('convert_currency', {
      amount: avgINR,
      from: 'INR',
      to: 'USD'
    });
    trace.push(`Converted ${avgINR} INR to USD`);
  } catch (err) {
    trace.push(`Error calling convert_currency: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: trace
    };
  }

  if (!conversionResult || (typeof conversionResult.converted !== 'number' && typeof conversionResult.amount !== 'number')) {
    trace.push(`Invalid conversion response.`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: trace
    };
  }

  const convertedUSD = typeof conversionResult.converted === 'number' ? conversionResult.converted : conversionResult.amount;

  return {
    status: 'success',
    answer: {
      value: Number(convertedUSD.toFixed(2)),
      unit: 'USD'
    },
    success_indicators: {
      matching_hotels_count: validPricesINR.length,
      average_price_inr: Number(avgINR.toFixed(2)),
      average_price_usd: Number(convertedUSD.toFixed(2))
    },
    trace: trace
  };
}
