        return res;
      } catch (err) {
        lastError = err;
        if (err && err.code === 'NOT_FOUND') {
          throw err; // Do not retry not found
        }
        trace.push(`Tool ${name} attempt ${attempt + 1} failed: ${err.message}`);
      }
