      trace.push('search_hotels returned error or empty');
    }

    const hotels = (Array.isArray(hotelsRaw) ? hotelsRaw : []).map(h => ({
      id: h.id,
      name: h.name,
      city: h.city,
      price_per_night: parseCost(h.price_per_night),
      veg_friendly: Boolean(h.veg_friendly)
    })).filter(h => h.veg_friendly);

    trace.push(`Found ${hotels.length} veg-friendly hotels`);

    trace.push(`Searching restaurants for city: ${city}`);
    let restaurantsRaw = [];
    try {
      restaurantsRaw = await callTool('search_restaurants', { city, veg_only: true });
    } catch (e) {
      trace.push('search_restaurants returned error or empty');
    }

    const restaurants = (Array.isArray(restaurantsRaw) ? restaurantsRaw : []).map(r => ({
      id: r.id,
      name: r.name,
      city: r.city,
      avg_cost_for_two: parseCost(r.avg_cost_for_two),
      veg: Boolean(r.veg)
    })).filter(r => r.veg);

    trace.push(`Found ${restaurants.length} vegetarian restaurants`);

    trace.push(`Listing attractions for city: ${city}`);
    let attractionsRaw = [];
    try {
      attractionsRaw = await callTool('list_attractions', { city });
    } catch (e) {
      trace.push('list_attractions returned error or empty');
    }

    const attractions = (Array.isArray(attractionsRaw) ? attractionsRaw : []).map(a => ({
      id: a.id,
      name: a.name,
      city: a.city,
      entry_fee: a.entry_fee === null ? 0 : parseCost(a.entry_fee)
    }));

    trace.push(`Found ${attractions.length} attractions`);

    if (hotels.length === 0 || restaurants.length === 0 || attractions.length === 0) {
      return {
        status: 'infeasible',
        answer: null,
        success_indicators: { reason: 'Missing necessary components (hotel, restaurant, or attraction) to form a plan.' },
        trace
      };
    }

    // Find combination within budget
    let bestPlan = null;
    let minCost = Infinity;

    for (const h of hotels) {
      for (const r of restaurants) {
        for (const a of attractions) {
          const hotelCost = h.price_per_night * 1; // 1 night
          const restCost = r.avg_cost_for_two;
          const attrCost = a.entry_fee;
          const total = hotelCost + restCost + attrCost;

          if (total <= budget && total < minCost) {
            minCost = total;
            bestPlan = [
              { kind: 'hotel', id: h.id, cost: hotelCost },
              { kind: 'attraction', id: a.id, cost: attrCost },
              { kind: 'restaurant', id: r.id, cost: restCost }
            ];
          }
        }
      }
    }

    if (!bestPlan) {
      return {
        status: 'infeasible',
        answer: null,
        success_indicators: { reason: 'No combination fits within the budget.' },
        trace
      };
    }

    return {
      status: 'success',
      answer: {
        plan: bestPlan,
        total_cost: minCost
      },
      success_indicators: { found: true },
      trace
    };

  } catch (err) {
    trace.push(`Execution error: ${err.message}`);
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }
}
