  } catch (err) {
    if (err && err.name === 'ToolError') {
      trace.push(`Geocode tool error: ${err.message}`);
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: err.message },
        trace
      };
    }
    throw err;
  }

  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    trace.push('No geocode results found for the city.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'City not found or invalid Indian city.' },
      trace
    };
  }

  const location = geoResults[0];
  const { latitude, longitude } = location;
  trace.push(`Found location: ${location.name} (${latitude}, ${longitude})`);

  // Step 2: Get air quality data
  let aqData;
  let attempts = 0;
  while (attempts < 3) {
    try {
      trace.push(`Fetching air quality for lat ${latitude}, lon ${longitude}, days ${days} (attempt ${attempts + 1})`);
      aqData = await tools.call('air_quality', { latitude, longitude, days });
      break;
    } catch (err) {
      attempts++;
      trace.push(`Air quality tool error on attempt ${attempts}: ${err.message}`);
      if (attempts >= 3) {
        return {
          status: 'failed_gracefully',
          answer: null,
          success_indicators: { error: err.message },
          trace
        };
      }
    }
  }

  if (!aqData || !Array.isArray(aqData.daily) || aqData.daily.length === 0) {
    trace.push('No daily air quality data returned.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No air quality data available for the given location and period.' },
      trace
    };
  }

  // Step 3: Compute average of daily mean PM2.5
  let sum = 0;
  let count = 0;
  for (const day of aqData.daily) {
    let pm25 = day.pm25_mean;
    if (typeof pm25 === 'string') {
      pm25 = parseFloat(pm25.replace(',', ''));
    }
    if (typeof pm25 === 'number' && !isNaN(pm25)) {
      sum += pm25;
      count++;
    }
  }

  if (count === 0) {
    trace.push('No valid pm25_mean values found in the daily data.');
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Air quality forecast has no valid PM2.5 measurements.' },
      trace
    };
  }

  const average = sum / count;
  trace.push(`Calculated average PM2.5: ${average} over ${count} days.`);

  return {
    status: 'success',
    answer: {
      value: average,
      unit: 'ug/m3'
    },
    success_indicators: { count },
    trace
  };
}
