async function run(task, tools, context) {
  const trace = [];

  // Helper for retrying transient tool errors (up to 2 retries)
  async function callToolWithRetry(toolName, args) {
    let retries = 0;
    while (true) {
      try {
        trace.push(
          `Calling ${toolName} with ${JSON.stringify(args)} (attempt ${
            retries + 1
          })`
        );
        const res = await tools.call(toolName, args);
        return res;
      } catch (err) {
        const isTransient =
          err &&
          err.name === 'ToolError' &&
          (err.code === 'UPSTREAM_503' ||
            err.code === 'TIMEOUT' ||
            err.code === 'NETWORK_ERROR');
        if (isTransient && retries < 2) {
          retries++;
          trace.push(
            `Transient error ${err.code} from ${toolName}. Retrying (${retries}/2)...`
          );
          continue;
        }
        trace.push(
          `Tool call ${toolName} failed: ${err ? err.message || err.code : err}`
        );
        throw err;
      }
    }
  }

  // 1. Input Validation
  const cityInput = task && task.inputs ? task.inputs.city : undefined;
  const daysInput = task && task.inputs ? task.inputs.days : undefined;

  let city = typeof cityInput === 'string' ? cityInput.trim() : '';
  let days = Number(daysInput);

  if (!city || isNaN(days) || !Number.isInteger(days) || days < 1 || days > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question:
          'Please provide a valid Indian city name and a number of days between 1 and 16.',
      },
      trace,
    };
  }

  // 2. Geocode City
  let geocodeResults;
  try {
    geocodeResults = await callToolWithRetry('geocode_city', {
      city: city,
      country_code: 'IN',
    });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Failed to geocode the specified city.' },
      trace,
    };
  }

  if (!Array.isArray(geocodeResults) || geocodeResults.length === 0) {
    // Try fallback without country code restriction just in case
    try {
      geocodeResults = await callToolWithRetry('geocode_city', { city: city });
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'Failed to geocode city on fallback.' },
        trace,
      };
    }
  }

  if (!Array.isArray(geocodeResults) || geocodeResults.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {
        reason: `Could not find any location matching city "${city}".`,
      },
      trace,
    };
  }

  // Filter or pick best match for India (IN)
  let bestMatch = geocodeResults.find(
    (item) => item && typeof item.country_code === 'string' && item.country_code.toUpperCase() === 'IN'
  );
  if (!bestMatch) {
    bestMatch = geocodeResults[0];
  }

  const lat = Number(bestMatch.latitude);
  const lon = Number(bestMatch.longitude);

  if (isNaN(lat) || isNaN(lon)) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Invalid coordinates received from geocoding.' },
      trace,
    };
  }

  // 3. Fetch Weather Forecast
  let forecastData;
  try {
    forecastData = await callToolWithRetry('weather_forecast', {
      latitude: lat,
      longitude: lon,
      days: days,
    });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Failed to retrieve weather forecast.' },
      trace,
    };
  }

  if (
    !forecastData ||
    !Array.isArray(forecastData.daily) ||
    forecastData.daily.length === 0
  ) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'No daily weather forecast data available.' },
      trace,
    };
  }

  // 4. Compute average daily max temp in Fahrenheit
  const dailyRecords = forecastData.daily.slice(0, days);
  let totalTempF = 0;
  let validDaysCount = 0;

  for (const day of dailyRecords) {
    if (day && day.temp_max_c !== undefined && day.temp_max_c !== null) {
      let tempC = Number(day.temp_max_c);
      if (typeof day.temp_max_c === 'string') {
        tempC = Number(String(day.temp_max_c).replace(',', ''));
      }
      if (!isNaN(tempC)) {
        const tempF = (tempC * 9) / 5 + 32;
        totalTempF += tempF;
        validDaysCount++;
      }
    }
  }

  if (validDaysCount === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Forecast data lacked valid temperature values.' },
      trace,
    };
  }

  const avgTempF = totalTempF / validDaysCount;
  const roundedAvgF = Math.round(avgTempF * 100) / 100;

  return {
    status: 'success',
    answer: {
      value: roundedAvgF,
      unit: 'Fahrenheit',
    },
    success_indicators: {
      city: bestMatch.name || city,
      country: bestMatch.country_code || 'IN',
      days_analyzed: validDaysCount,
      avg_temp_f: roundedAvgF,
    },
    trace,
  };
}
