async function run(task, tools, context) {
  const trace = [];
  const successIndicators = {};

  // ---------- Input validation ----------
  const { city, days } = task.inputs || {};

  if (typeof city !== 'string' || city.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid city name.' },
      trace
    };
  }

  if (
    typeof days !== 'number' ||
    !Number.isInteger(days) ||
    days < 1 ||
    days > 5
  ) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a days value between 1 and 5.' },
      trace
    };
  }

  // ---------- Geocode city ----------
  const geocode = async () => {
    try {
      trace.push('Calling geocode_city');
      const results = await tools.call('geocode_city', { city, country_code: 'IN' });
      if (!Array.isArray(results) || results.length === 0) {
        throw new Error('No city found');
      }
      // Validate first result
      const loc = results[0];
      if (
        typeof loc.latitude !== 'number' ||
        typeof loc.longitude !== 'number'
      ) {
        throw new Error('Invalid geocode output');
      }
      return { latitude: loc.latitude, longitude: loc.longitude };
    } catch (e) {
      throw e;
    }
  };

  let coords;
  try {
    coords = await retry(geocode, 2, trace);
  } catch (e) {
    if (e.name === 'ToolError' && e.code === 'NOT_FOUND') {
      return {
        status: 'needs_clarification',
        answer: null,
        success_indicators: { question: `City "${city}" not found.` },
        trace
      };
    }
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: e.message },
      trace
    };
  }

  // ---------- Air quality forecast ----------
  const airQuality = async () => {
    try {
      trace.push('Calling air_quality');
      const result = await tools.call('air_quality', {
        latitude: coords.latitude,
        longitude: coords.longitude,
        days
      });
      if (!result || !Array.isArray(result.daily)) {
        throw new Error('Invalid air_quality output');
      }
      // Validate each daily entry
      const daily = result.daily.map((d, idx) => {
        if (
          typeof d.date !== 'string' ||
          typeof d.pm25_mean !== 'number' ||
          typeof d.us_aqi_max !== 'number'
        ) {
          throw new Error(`Invalid daily data at index ${idx}`);
        }
        return d;
      });
      return daily;
    } catch (e) {
      throw e;
    }
  };

  let dailyData;
  try {
    dailyData = await retry(airQuality, 2, trace);
  } catch (e) {
    if (e.name === 'ToolError' && e.code === 'TIMEOUT') {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: 'Air quality service timed out.' },
        trace
      };
    }
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: e.message },
      trace
    };
  }

  // ---------- Compute average ----------
  const sum = dailyData.reduce((acc, d) => acc + d.pm25_mean, 0);
  const avg = sum / dailyData.length;

  // ---------- Return success ----------
  return {
    status: 'success',
    answer: { value: avg, unit: 'µg/m³' },
    success_indicators: {},
    trace
  };

  // ---------- Helper: retry ----------
  async function retry(fn, attempts, traceArray) {
    let lastError;
    for (let i = 0; i < attempts; i++) {
      try {
        return await fn();
      } catch (e) {
        lastError = e;
        if (
          e.name === 'ToolError' &&
          ['UPSTREAM_503', 'TIMEOUT', 'UNKNOWN_TOOL'].includes(e.code)
        ) {
          traceArray.push(`Retry ${i + 1} after transient error: ${e.code}`);
          continue;
        } else {
          throw e;
        }
      }
    }
    throw lastError;
  }
}
