async function run(task, tools, context) {
  const trace = [];
  const inputs = task.inputs || {};

  // Validate inputs
  const cityA = inputs.city_a;
  const cityB = inputs.city_b;
  const days = inputs.days;

  if (!cityA || typeof cityA !== 'string' || cityA.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid Indian city for city_a.' },
      trace: ['Missing or invalid city_a']
    };
  }

  if (!cityB || typeof cityB !== 'string' || cityB.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid Indian city for city_b.' },
      trace: ['Missing or invalid city_b']
    };
  }

  if (typeof days !== 'number' || !Number.isInteger(days) || days < 1 || days > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a valid number of days between 1 and 16.' },
      trace: ['Missing or invalid days parameter']
    };
  }

  // Helper function to call tools with retry logic
  async function callToolWithRetry(name, args, maxRetries = 2) {
    let attempt = 0;
    while (true) {
      try {
        attempt++;
        return await tools.call(name, args);
      } catch (error) {
        const isTransient = error && (
          error.code === 'UPSTREAM_503' || 
          error.code === 'TIMEOUT' || 
          (error.message && /timeout|503|temporary|network/i.test(error.message))
        );
        if (isTransient && attempt <= maxRetries) {
          trace.push(`Tool ${name} failed with transient error (attempt ${attempt}), retrying...`);
          continue;
        }
        throw error;
      }
    }
  }

  // Helper to geocode a city in India
  async function getCoordinates(cityName) {
    let results;
    try {
      results = await callToolWithRetry('geocode_city', { city: cityName, country_code: 'IN' });
    } catch (e) {
      throw new Error(`Failed to geocode ${cityName}: ${e.message}`);
    }

    if (!Array.isArray(results) || results.length === 0) {
      // Try without country_code restriction just in case
      try {
        results = await callToolWithRetry('geocode_city', { city: cityName });
      } catch (e) {
        throw new Error(`Failed to geocode ${cityName}: ${e.message}`);
      }
    }

    if (!Array.isArray(results) || results.length === 0) {
      return null;
    }

    const match = results[0];
    if (typeof match.latitude !== 'number' || typeof match.longitude !== 'number') {
      return null;
    }

    return { latitude: match.latitude, longitude: match.longitude };
  }

  let coordsA, coordsB;
  try {
    trace.push(`Geocoding city_a: ${cityA}`);
    coordsA = await getCoordinates(cityA);
    if (!coordsA) {
      return {
        status: 'infeasible',
        answer: null,
        success_indicators: { error: `Could not find coordinates for city_a: ${cityA}` },
        trace
      };
    }

    trace.push(`Geocoding city_b: ${cityB}`);
    coordsB = await getCoordinates(cityB);
    if (!coordsB) {
      return {
        status: 'infeasible',
        answer: null,
        success_indicators: { error: `Could not find coordinates for city_b: ${cityB}` },
        trace
      };
    }
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace
    };
  }

  // Fetch forecasts
  let forecastA, forecastB;
  try {
    trace.push(`Fetching weather forecast for ${cityA} for ${days} days`);
    forecastA = await callToolWithRetry('weather_forecast', {
      latitude: coordsA.latitude,
      longitude: coordsA.longitude,
      days: days
    });

    trace.push(`Fetching weather forecast for ${cityB} for ${days} days`);
    forecastB = await callToolWithRetry('weather_forecast', {
      latitude: coordsB.latitude,
      longitude: coordsB.longitude,
      days: days
    });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `Weather forecast tool failed: ${err.message}` },
      trace
    };
  }

  // Validate and parse forecasts
  if (!forecastA || !Array.isArray(forecastA.daily) || forecastA.daily.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `No daily forecast data returned for ${cityA}` },
      trace
    };
  }

  if (!forecastB || !Array.isArray(forecastB.daily) || forecastB.daily.length === 0) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: `No daily forecast data returned for ${cityB}` },
      trace
    };
  }

  function parseTempMax(val) {
    if (typeof val === 'number') return val;
    if (typeof val === 'string') {
      const cleaned = val.replace(/,/g, '').trim();
      const num = parseFloat(cleaned);
      if (!isNaN(num)) return num;
    }
    return null;
  }

  // Extract and calculate average daily maximum temperatures
  const tempsA = forecastA.daily.slice(0, days).map(d => parseTempMax(d.temp_max_c));
  const tempsB = forecastB.daily.slice(0, days).map(d => parseTempMax(d.temp_max_c));

  if (tempsA.some(t => t === null) || tempsB.some(t => t === null)) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: 'Invalid temperature data received from forecast' },
      trace
    };
  }

  const avgA = tempsA.reduce((sum, t) => sum + t, 0) / tempsA.length;
  const avgB = tempsB.reduce((sum, t) => sum + t, 0) / tempsB.length;

  const diff = avgA - avgB;
  // Round to a reasonable precision if needed, but keeping float is fine
  const roundedDiff = Number(diff.toFixed(4));

  trace.push(`Avg max temp for ${cityA}: ${avgA}, Avg max temp for ${cityB}: ${avgB}, Difference (A-B): ${roundedDiff}`);

  return {
    status: 'success',
    answer: {
      value: roundedDiff,
      unit: 'Celsius'
    },
    success_indicators: {
      city_a: cityA,
      city_b: cityB,
      days: days,
      avg_temp_a: avgA,
      avg_temp_b: avgB
    },
    trace
  };
}
