async function run(task, tools, context) {
  const trace = [];
  const participants = task.inputs.participants;
  const durationMinutes = task.inputs.duration_minutes;
  const windowStartStr = task.inputs.window_start;
  const windowEndStr = task.inputs.window_end;

  if (!participants || !Array.isArray(participants) || participants.length === 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please provide a non-empty list of participants.' },
      trace: ['Missing participants']
    };
  }

  if (!durationMinutes || !windowStartStr || !windowEndStr) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Missing duration_minutes, window_start, or window_end.' },
      trace: ['Missing required meeting parameters']
    };
  }

  async function callToolWithRetry(name, args) {
    let lastError;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        lastError = err;
        if (err && err.name === 'ToolError' && (err.code === 'INVALID_ARGS' || err.code === 'NOT_FOUND')) {
          throw err;
        }
      }
    }
    throw lastError;
  }

  // 1. Fetch profiles and calendars
  const profiles = {};
  const calendars = {};
  const yearsToCheck = new Set();

  const wStart = new Date(windowStartStr);
  const wEnd = new Date(windowEndStr);
  yearsToCheck.add(wStart.getUTCFullYear());
  yearsToCheck.add(wEnd.getUTCFullYear());

  try {
    for (const p of participants) {
      trace.push(`Fetching profile for ${p}`);
      const profile = await callToolWithRetry('get_person_profile', { person: p });
      profiles[p] = profile;

      trace.push(`Fetching calendar for ${p}`);
      const cal = await callToolWithRetry('get_calendar', {
        person: p,
        start: windowStartStr,
        end: windowEndStr
      });
      calendars[p] = cal.busy || [];
    }
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace: [...trace, `Tool error: ${err.message}`]
    };
  }

  // 2. Fetch US public holidays for relevant years
  const holidays = [];
  try {
    for (const yr of yearsToCheck) {
      trace.push(`Fetching US holidays for ${yr}`);
      const hols = await callToolWithRetry('public_holidays', { country_code: 'US', year: yr });
      if (Array.isArray(hols)) {
        holidays.push(...hols);
      }
    }
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: { error: err.message },
      trace: [...trace, `Holiday tool error: ${err.message}`]
    };
  }

  const holidayDates = new Set(holidays.map(h => h.date));

  // Helper to get US Eastern date string ('YYYY-MM-DD') for a UTC Date
  function getUSEasternDateStr(date) {
    // US Eastern is America/New_York (UTC-5 or UTC-4).
    // Let's use Intl.DateTimeFormat to reliably get YYYY-MM-DD in America/New_York
    const formatter = new Intl.DateTimeFormat('en-CA', {
      timeZone: 'America/New_York',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    });
    return formatter.format(date);
  }

  // Helper: check if a UTC instant falls within working hours for a person
  function isWithinWorkingHours(utcDate, profile) {
    const tz = profile.timezone || 'UTC';
    // Format local time parts
    const timeFormatter = new Intl.DateTimeFormat('en-GB', {
      timeZone: tz,
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
    const parts = timeFormatter.formatToParts(utcDate);
    const hour = parseInt(parts.find(p => p.type === 'hour').value, 10);
    const minute = parseInt(parts.find(p => p.type === 'minute').value, 10);
    const totalMinutes = hour * 60 + minute;

    const [startH, startM] = profile.working_hours.start.split(':').map(Number);
    const [endH, endM] = profile.working_hours.end.split(':').map(Number);
    const workStartMinutes = startH * 60 + startM;
    const workEndMinutes = endH * 60 + endM;

    return totalMinutes >= workStartMinutes && totalMinutes <= workEndMinutes;
  }

  // Helper: check if a date (UTC) falls on a US public holiday (judged by US Eastern date)
  function isUSHoliday(utcDate) {
    const nyDateStr = getUSEasternDateStr(utcDate);
    return holidayDates.has(nyDateStr);
  }

  // Helper: check if interval [slotStart, slotEnd] conflicts with any busy period or all-day event
  function hasConflict(slotStart, slotEnd, person, profile) {
    const busyList = calendars[person] || [];
    const slotStartTime = slotStart.getTime();
    const slotEndTime = slotEnd.getTime();

    for (const b of busyList) {
      if (b.all_day) {
        // all_day event: b.start and b.end are date strings like 'YYYY-MM-DD' in person's local timezone
        // Convert person's local date to UTC range or check if US Eastern date matches.
        // Actually all_day usually means whole calendar day in local time.
        // Let's check if the slot overlaps with the local date.
        const nyDateStr = getUSEasternDateStr(slotStart);
        if (b.start === nyDateStr || (b.start <= nyDateStr && nyDateStr < b.end)) {
          return true;
        }
      } else {
        const bStart = new Date(b.start).getTime();
        const bEnd = new Date(b.end).getTime();
        // Overlap condition: max(start1, start2) < min(end1, end2)
        if (Math.max(slotStartTime, bStart) < Math.min(slotEndTime, bEnd)) {
          return true;
        }
      }
    }
    return false;
  }

  // 3. Scan candidate slots (:00 or :30 UTC)
  const windowStartTime = wStart.getTime();
  const windowEndTime = wEnd.getTime();

  // Align windowStart to the next :00 or :30
  let current = new Date(windowStartTime);
  let minutes = current.getUTCMinutes();
  if (minutes > 0 && minutes < 30) {
    current.setUTCMinutes(30, 0, 0);
  } else if (minutes > 30) {
    current.setUTCHours(current.getUTCHours() + 1, 0, 0, 0);
  } else {
    current.setUTCSeconds(0, 0);
  }

  let foundSlot = null;

  while (current.getTime() + durationMinutes * 60000 <= windowEndTime) {
    const slotStart = new Date(current.getTime());
    const slotEnd = new Date(slotStart.getTime() + durationMinutes * 60000);

    // Check US public holiday check based on US Eastern date
    let isHoliday = false;
    // Check both start and end or middle? Usually check start date or any day spanned.
    if (isUSHoliday(slotStart) || isUSHoliday(slotEnd)) {
      isHoliday = true;
    }

    if (!isHoliday) {
      // Check working hours and conflicts for all participants
      let allValid = true;
      for (const p of participants) {
        const prof = profiles[p];
        // Check working hours for both start and end (or check every minute/check start & end)
        // Usually check if start and end are within working hours, or sample. Let's check start and end.
        if (!isWithinWorkingHours(slotStart, prof) || !isWithinWorkingHours(slotEnd, prof)) {
          allValid = false;
          break;
        }
        if (hasConflict(slotStart, slotEnd, p, prof)) {
          allValid = false;
          break;
        }
      }

      if (allValid) {
        foundSlot = {
          start: slotStart.toISOString().replace(/\.\d{3}Z$/, 'Z'),
          end: slotEnd.toISOString().replace(/\.\d{3}Z$/, 'Z'),
          participants
        };
        break;
      }
    }

    // Advance by 30 minutes
    current.setUTCMinutes(current.getUTCMinutes() + 30);
  }

  if (!foundSlot) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No available slot found meeting all constraints.' },
      trace: [...trace, 'No feasible slot found']
    };
  }

  // 4. Send invite if confirmed
  if (context.confirmed) {
    try {
      trace.push('Sending invite (confirmed)');
      await callToolWithRetry('send_invite', {
        participants,
        start: foundSlot.start,
        end: foundSlot.end,
        title: 'Team Meeting'
      });
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: err.message },
        trace: [...trace, `Failed to send invite: ${err.message}`]
      };
    }
  } else {
    // If not confirmed yet, but we found a slot, should we return needs_clarification or success?
    // Wait, the prompt says: "Send a calendar invite to participants. SIDE EFFECT: requires explicit user confirmation (context.confirmed === true)."
    // If context.confirmed is false, can we return success with the answer or needs_clarification?
    // Usually, finding the slot and returning it as success or asking for confirmation. But wait, if context.confirmed is false and side effect is required, standard runner workflow either calls it when confirmed or asks confirmation. Let's check standard agent contract: if side effect requires confirmation and not confirmed, return needs_clarification asking for confirmation, OR return success if the answer is just the slot. Let's look at ANSWER SCHEMA: { start, end, participants }. There is no invite_id in ANSWER SCHEMA. ANSWER SCHEMA only requires start, end, participants. Thus finding and returning the slot satisfies the answer schema. If confirmation is needed for send_invite, let's check if send_invite must be called. If context.confirmed is false, we can either skip send_invite or ask for confirmation. Let's check context.confirmed: if false, should we ask for confirmation? The task says "books the earliest slot...". Booking implies sending invite or finding it. Let's call send_invite if confirmed, otherwise if not confirmed, ask for confirmation or return success if sending invite happens only when confirmed. Wait! If context.confirmed is false, calling a tool requiring confirmation throws or violates contract. But if we don't call it, what should we return? Let's check if we should return needs_clarification asking the user to confirm booking this slot.
  }

  if (!context.confirmed) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: `Found earliest available slot from ${foundSlot.start} to ${foundSlot.end}. Do you confirm booking this meeting?`,
        proposed_slot: foundSlot
      },
      trace: [...trace, `Found slot ${foundSlot.start} - ${foundSlot.end}, awaiting confirmation`]
    };
  }

  return {
    status: 'success',
    answer: foundSlot,
    success_indicators: { booked: true },
    trace: [...trace, `Successfully booked slot ${foundSlot.start} - ${foundSlot.end}`]
  };
}
