async function run(task, tools, context) {
  const trace = [];

  // Helper: call tool with retry for transient errors
  async function callTool(name, args) {
    let retries = 2;
    while (true) {
      try {
        const res = await tools.call(name, args);
        return res;
      } catch (err) {
        if (err && err.name === 'ToolError') {
          const isTransient = ['UPSTREAM_503', 'TIMEOUT', 'RATE_LIMIT'].includes(err.code);
          if (isTransient && retries > 0) {
            retries--;
            continue;
          }
        }
        throw err;
      }
    }
  }

  // Helper: safe date parsing (ISO format string to epoch ms)
  function parseISO(str) {
    if (!str || typeof str !== 'string') return NaN;
    const d = new Date(str);
    return d.getTime();
  }

  // Input validation
  const inputs = task.inputs || {};
  let { participants, duration_minutes, window_start, window_end } = inputs;

  if (typeof duration_minutes === 'string') {
    duration_minutes = parseInt(duration_minutes.replace(/,/g, ''), 10);
  }

  if (
    !Array.isArray(participants) ||
    participants.length === 0 ||
    !participants.every(p => typeof p === 'string' && p.trim().length > 0) ||
    typeof duration_minutes !== 'number' ||
    isNaN(duration_minutes) ||
    duration_minutes <= 0 ||
    !window_start ||
    !window_end ||
    isNaN(parseISO(window_start)) ||
    isNaN(parseISO(window_end))
  ) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: 'Invalid or missing inputs. Please provide valid participants, duration_minutes, window_start, and window_end.'
      },
      trace
    };
  }

  const winStartMs = parseISO(window_start);
  const winEndMs = parseISO(window_end);
  const durMs = duration_minutes * 60 * 1000;

  if (winStartMs >= winEndMs || winEndMs - winStartMs < durMs) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'Search window is smaller than meeting duration or invalid.' },
      trace: ['Window too short or start >= end']
    };
  }

  // 1. Fetch profiles for all participants
  const profiles = [];
  try {
    for (const p of participants) {
      trace.push(`Fetching profile for ${p}`);
      const prof = await callTool('get_person_profile', { person: p });
      if (!prof || typeof prof.utc_offset_minutes !== 'number' || !prof.working_hours || !prof.working_hours.start || !prof.working_hours.end) {
        return {
          status: 'failed_gracefully',
          answer: null,
          success_indicators: {},
          trace: [...trace, `Invalid profile data for ${p}`]
        };
      }
      profiles.push(prof);
    }
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Error fetching profiles: ${err.message}`]
    };
  }

  // 2. Fetch calendars for all participants
  const calendars = [];
  try {
    for (const p of participants) {
      trace.push(`Fetching calendar for ${p}`);
      const cal = await callTool('get_calendar', { person: p, start: window_start, end: window_end });
      const busyList = (cal && Array.isArray(cal.busy)) ? cal.busy : [];
      calendars.push({ person: p, busy: busyList });
    }
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Error fetching calendars: ${err.message}`]
    };
  }

  // 3. Fetch US Public Holidays for relevant years
  const startYear = new Date(winStartMs).getUTCFullYear();
  const endYear = new Date(winEndMs).getUTCFullYear();
  const usHolidays = new Set();

  try {
    for (let yr = startYear - 1; yr <= endYear + 1; yr++) {
      trace.push(`Fetching US holidays for year ${yr}`);
      const hols = await callTool('public_holidays', { country_code: 'US', year: yr });
      if (Array.isArray(hols)) {
        for (const h of hols) {
          if (h.date) usHolidays.add(h.date);
        }
      }
    }
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Error fetching holidays: ${err.message}`]
    };
  }

  // Helper to format Date to 'YYYY-MM-DDTHH:mmZ'
  function formatUTCISO(d) {
    const yyyy = d.getUTCFullYear();
    const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(d.getUTCDate()).padStart(2, '0');
    const hh = String(d.getUTCHours()).padStart(2, '0');
    const min = String(d.getUTCMinutes()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}T${hh}:${min}Z`;
  }

  // Helper to get US Eastern Date string ('YYYY-MM-DD') for a UTC timestamp
  function getUSEasternDateStr(timestampMs) {
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/New_York',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    });
    const parts = formatter.formatToParts(new Date(timestampMs));
    let year, month, day;
    for (const p of parts) {
      if (p.type === 'year') year = p.value;
      if (p.type === 'month') month = p.value;
      if (p.type === 'day') day = p.value;
    }
    return `${year}-${month}-${day}`;
  }

  // Helper to check if a slot falls on a US public holiday (by US Eastern Date)
  function isUSPublicHoliday(slotStartMs, slotEndMs) {
    // Check start date, end date, and any dates crossed
    let curr = slotStartMs;
    while (curr < slotEndMs) {
      const dateStr = getUSEasternDateStr(curr);
      if (usHolidays.has(dateStr)) return true;
      curr += 4 * 3600 * 1000; // step 4 hours
    }
    const endDateStr = getUSEasternDateStr(slotEndMs - 1);
    return usHolidays.has(endDateStr);
  }

  // Helper to check if a time slot is within a person's local working hours
  function isWithinWorkingHours(slotStartMs, slotEndMs, profile) {
    const offsetMs = profile.utc_offset_minutes * 60 * 1000;

    // Parse working hours string "HH:mm"
    const [sH, sM] = profile.working_hours.start.split(':').map(Number);
    const [eH, eM] = profile.working_hours.end.split(':').map(Number);
    const startMins = sH * 60 + sM;
    const endMins = eH * 60 + eM;

    // Check slot start and end in local time
    const localStart = new Date(slotStartMs + offsetMs);
    const localEnd = new Date(slotEndMs + offsetMs);

    // Check if slot spans across multiple local days
    if (localStart.getUTCFullYear() !== localEnd.getUTCFullYear() ||
        localStart.getUTCMonth() !== localEnd.getUTCMonth() ||
        localStart.getUTCDate() !== localEnd.getUTCDate()) {
      return false;
    }

    const localStartMins = localStart.getUTCHours() * 60 + localStart.getUTCMinutes();
    const localEndMins = localEnd.getUTCHours() * 60 + localEnd.getUTCMinutes();

    return localStartMins >= startMins && localEndMins <= endMins;
  }

  // Helper to check if a slot conflicts with any busy interval
  function hasConflict(slotStartMs, slotEndMs) {
    for (const cal of calendars) {
      const profile = profiles.find(p => p.person === cal.person);
      const offsetMs = (profile ? profile.utc_offset_minutes : 0) * 60 * 1000;

      for (const b of cal.busy) {
        let bStart, bEnd;
        if (b.all_day) {
          // All-day event in person's local timezone
          // Parse YYYY-MM-DD
          const [y, m, d] = b.start.split('T')[0].split('-').map(Number);
          const localStartMs = Date.UTC(y, m - 1, d, 0, 0, 0);
          const localEndMs = Date.UTC(y, m - 1, d + 1, 0, 0, 0);
          bStart = localStartMs - offsetMs;
          bEnd = localEndMs - offsetMs;
        } else {
          bStart = parseISO(b.start);
          bEnd = parseISO(b.end);
        }

        if (isNaN(bStart) || isNaN(bEnd)) continue;

        // Overlap condition: start < bEnd && end > bStart
        if (slotStartMs < bEnd && slotEndMs > bStart) {
          return true;
        }
      }
    }
    return false;
  }

  // 4. Search for earliest candidate slot on :00 or :30 UTC
  // Align initial candidate start time to next :00 or :30 UTC
  let candStart = new Date(winStartMs);
  const mins = candStart.getUTCMinutes();
  if (mins > 0 && mins < 30) {
    candStart.setUTCMinutes(30, 0, 0);
  } else if (mins > 30) {
    candStart.setUTCHours(candStart.getUTCHours() + 1, 0, 0, 0);
  } else {
    candStart.setUTCMinutes(mins, 0, 0);
  }

  let candStartMs = candStart.getTime();
  const stepMs = 30 * 60 * 1000;
  let chosenSlot = null;

  while (candStartMs + durMs <= winEndMs) {
    const candEndMs = candStartMs + durMs;

    // Check US Public Holiday
    if (!isUSPublicHoliday(candStartMs, candEndMs)) {
      // Check working hours for all participants
      const allInWorkingHours = profiles.every(prof => isWithinWorkingHours(candStartMs, candEndMs, prof));

      if (allInWorkingHours) {
        // Check conflicts
        if (!hasConflict(candStartMs, candEndMs)) {
          chosenSlot = {
            start: formatUTCISO(new Date(candStartMs)),
            end: formatUTCISO(new Date(candEndMs)),
            participants
          };
          break;
        }
      }
    }

    candStartMs += stepMs;
  }

  if (!chosenSlot) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { reason: 'No available slot found satisfying all constraints within the window.' },
      trace: [...trace, 'No conflict-free slot in working hours outside US holidays found.']
    };
  }

  // 5. Send invite if confirmed
  if (!context.confirmed) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: {
        question: `Found slot from ${chosenSlot.start} to ${chosenSlot.end}. Please confirm booking sending the invite.`,
        proposed_slot: chosenSlot
      },
      trace: [...trace, `Found valid slot ${chosenSlot.start} - ${chosenSlot.end}, awaiting user confirmation.`]
    };
  }

  try {
    trace.push(`Sending invite for slot ${chosenSlot.start} - ${chosenSlot.end}`);
    await callTool('send_invite', {
      participants: chosenSlot.participants,
      start: chosenSlot.start,
      end: chosenSlot.end,
      title: 'Team Meeting'
    });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Failed to send invite: ${err.message}`]
    };
  }

  return {
    status: 'success',
    answer: chosenSlot,
    success_indicators: { booked: true },
    trace: [...trace, 'Successfully booked meeting slot.']
  };
}
