async function run(task, tools, context) {
  const trace = [];
  const { city, days, unit } = task.inputs || {};

  // 1. Validate inputs
  if (!city || typeof city !== 'string' || city.trim() === '') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please specify a valid Indian city name.' },
      trace: ['Invalid or missing city input.']
    };
  }

  const parsedDays = Number(days);
  if (!Number.isInteger(parsedDays) || parsedDays < 1 || parsedDays > 16) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please specify a number of days between 1 and 16.' },
      trace: ['Invalid or missing days input (must be 1..16).']
    };
  }

  if (unit !== 'mm' && unit !== 'in') {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Please specify a valid unit for precipitation: "mm" or "in".' },
      trace: ['Invalid or missing unit input (must be "mm" or "in").']
    };
  }

  // Helper function for robust tool calls with retry
  async function callToolWithRetry(name, args, maxRetries = 2) {
    let attempt = 0;
    while (true) {
      try {
        trace.push(`Calling tool ${name} (attempt ${attempt + 1})`);
        const result = await tools.call(name, args);
        return result;
      } catch (err) {
        attempt++;
        const code = err && err.code ? err.code : 'UNKNOWN';
        trace.push(`Tool ${name} failed with code ${code}: ${err.message}`);

        // Decide whether to retry (retry on transient errors like TIMEOUT, UPSTREAM_503, etc.)
        const isTransient = ['TIMEOUT', 'UPSTREAM_503', 'RATE_LIMITED', 'UNKNOWN'].includes(code);
        if (attempt > maxRetries || !isTransient) {
          throw err;
        }
        // Small backoff concept represented just by looping
      }
    }
  }

  // 2. Geocode city (restrict to 'IN' for India as per spec)
  let geoResults;
  try {
    geoResults = await callToolWithRetry('geocode_city', { city: city.trim(), country_code: 'IN' });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Geocoding failed: ${err.message}`]
    };
  }

  if (!Array.isArray(geoResults) || geoResults.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: [...trace, `No geocoding results found for city: ${city} in India.`]
    };
  }

  const location = geoResults[0];
  const lat = Number(location.latitude);
  const lon = Number(location.longitude);

  if (isNaN(lat) || isNaN(lon)) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Invalid coordinates returned for city: ${city}`]
    };
  }

  // 3. Fetch weather forecast
  let forecastResult;
  try {
    forecastResult = await callToolWithRetry('weather_forecast', {
      latitude: lat,
      longitude: lon,
      days: parsedDays
    });
  } catch (err) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, `Weather forecast failed: ${err.message}`]
    };
  }

  if (!forecastResult || !Array.isArray(forecastResult.daily)) {
    return {
      status: 'failed_gracefully',
      answer: null,
      success_indicators: {},
      trace: [...trace, 'Weather forecast returned invalid or empty daily data.']
    };
  }

  const daily = forecastResult.daily;
  if (daily.length === 0) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: [...trace, 'Weather forecast returned zero daily records.']
    };
  }

  // 4. Sum up precipitation (coerce values robustly)
  let totalMm = 0;
  for (let i = 0; i < Math.min(parsedDays, daily.length); i++) {
    const dayData = daily[i];
    let precip = dayData.precipitation_mm;

    if (typeof precip === 'string') {
      // Coerce numeric strings like "4,500" or "1.5"
      precip = Number(precip.replace(/,/g, ''));
    }

    if (typeof precip === 'number' && !isNaN(precip)) {
      totalMm += precip;
    }
  }

  // 5. Convert unit if requested ('in')
  let finalValue = totalMm;
  if (unit === 'in') {
    // 1 inch = 25.4 millimeters
    finalValue = totalMm / 25.4;
  }

  // Round to reasonable precision (e.g. 2 decimal places)
  finalValue = Number(finalValue.toFixed(2));

  trace.push(`Successfully calculated precipitation: ${finalValue} ${unit}`);

  return {
    status: 'success',
    answer: {
      value: finalValue,
      unit: unit
    },
    success_indicators: {
      city_resolved: location.name,
      days_counted: Math.min(parsedDays, daily.length)
    },
    trace
  };
}
