async function run(task, tools, context) {
  const trace = [];
  const participants = task.inputs.participants || [];
  const durationMinutes = task.inputs.duration_minutes;
  const windowStartStr = task.inputs.window_start;
  const windowEndStr = task.inputs.window_end;
  const title = task.inputs.title || 'Meeting';

  if (!participants.length || !durationMinutes || !windowStartStr || !windowEndStr) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Missing required inputs: participants, duration_minutes, window_start, or window_end.' },
      trace: ['Missing inputs']
    };
  }

  async function callToolWithRetry(name, args, retries = 2) {
    for (let attempt = 0; attempt <= retries; attempt++) {
      try {
        return await tools.call(name, args);
      } catch (err) {
        trace.push(`Tool ${name} failed: ${err.message} (attempt ${attempt + 1})`);
        if (attempt === retries || (err.name === 'ToolError' && ['INVALID_ARGS', 'NOT_FOUND'].includes(err.code))) {
          throw err;
        }
      }
    }
  }

  // 1. Fetch profiles for all participants
  const profiles = {};
  for (const person of participants) {
    try {
      const profile = await callToolWithRetry('get_person_profile', { person });
      profiles[person] = profile;
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to get profile for ${person}: ${err.message}` },
        trace
      };
    }
  }

  // 2. Fetch calendar busy slots for all participants within the window
  const busySchedules = {};
  for (const person of participants) {
    try {
      const cal = await callToolWithRetry('get_calendar', {
        person,
        start: windowStartStr,
        end: windowEndStr
      });
      busySchedules[person] = cal.busy || [];
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to get calendar for ${person}: ${err.message}` },
        trace
      };
    }
  }

  // Parse window boundaries as UTC Date objects
  const windowStart = new Date(windowStartStr);
  const windowEnd = new Date(windowEndStr);

  // Generate candidate slots on :00 or :30 UTC
  // Align windowStart up to the next :00 or :30
  let candidateStart = new Date(windowStart);
  candidateStart.setUTCSeconds(0, 0);
  const minutes = candidateStart.getUTCMinutes();
  if (minutes > 0 && minutes < 30) {
    candidateStart.setUTCMinutes(30);
  } else if (minutes > 30) {
    candidateStart.setUTCHours(candidateStart.getUTCHours() + 1);
    candidateStart.setUTCMinutes(0);
  }

  let foundSlot = null;

  while (true) {
    const candidateEnd = new Date(candidateStart.getTime() + durationMinutes * 60000);
    if (candidateEnd > windowEnd) break;

    let isConflictFree = true;

    for (const person of participants) {
      const profile = profiles[person];
      const offsetMin = profile.utc_offset_minutes || 0;

      // Check working hours locally for this person
      // candidateStart in person's local time:
      const personStartLocal = new Date(candidateStart.getTime() + offsetMin * 60000);
      const personEndLocal = new Date(candidateEnd.getTime() + offsetMin * 60000);

      const localHour = personStartLocal.getUTCHours();
      const localMin = personStartLocal.getUTCMinutes();
      const localEndHour = personEndLocal.getUTCHours();
      const localEndMin = personEndLocal.getUTCMinutes();

      const [whStartH, whStartM] = profile.working_hours.start.split(':').map(Number);
      const [whEndH, whEndM] = profile.working_hours.end.split(':').map(Number);

      const localStartMinutes = localHour * 60 + localMin;
      const localEndMinutes = localEndHour * 60 + localEndMin;
      const whStartMinutes = whStartH * 60 + whStartM;
      const whEndMinutes = whEndH * 60 + whEndM;

      if (localStartMinutes < whStartMinutes || localEndMinutes > whEndMinutes) {
        isConflictFree = false;
        break;
      }

      // Check busy intervals
      const busyList = busySchedules[person];
      for (const b of busyList) {
        if (b.all_day) {
          // All day event: parse date YYYY-MM-DD and check if candidate date matches local date
          const localDateStr = personStartLocal.toISOString().slice(0, 10);
          if (b.start <= localDateStr && localDateStr <= b.end) {
            isConflictFree = false;
            break;
          }
        } else {
          const bStart = new Date(b.start).getTime();
          const bEnd = new Date(b.end).getTime();
          const cStart = candidateStart.getTime();
          const cEnd = candidateEnd.getTime();

          // Overlap condition: start1 < end2 and start2 < end1
          if (cStart < bEnd && bStart < cEnd) {
            isConflictFree = false;
            break;
          }
        }
      }

      if (!isConflictFree) break;
    }

    if (isConflictFree) {
      foundSlot = {
        start: candidateStart.toISOString().replace('.000Z', 'Z'),
        end: candidateEnd.toISOString().replace('.000Z', 'Z'),
        participants
      };
      break;
    }

    // Increment by 30 minutes
    candidateStart = new Date(candidateStart.getTime() + 30 * 60000);
  }

  if (!foundSlot) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: { message: 'No conflict-free slot found within the window and working hours.' },
      trace
    };
  }

  // If found, check if we should send invite
  if (context.confirmed) {
    try {
      await callToolWithRetry('send_invite', {
        participants,
        start: foundSlot.start,
        end: foundSlot.end,
        title
      });
      trace.push('Invite sent successfully.');
    } catch (err) {
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: { error: `Failed to send invite: ${err.message}` },
        trace
      };
    }
  } else {
    trace.push('Not confirmed; returning proposed slot without sending invite.');
  }

  return {
    status: 'success',
    answer: foundSlot,
    success_indicators: { slot_found: true, invited: !!context.confirmed },
    trace
  };
}
