    return { status: 'needs_clarification', answer: null, success_indicators: { question: 'duration_minutes must be a positive integer.' }, trace };
  }
  if (typeof window_start !== 'string' || typeof window_end !== 'string') {
    return { status: 'needs_clarification', answer: null, success_indicators: { question: 'window_start and window_end must be ISO strings.' }, trace };
  }
  const startTime = new Date(window_start);
  const endTime = new Date(window_end);
  if (isNaN(startTime) || isNaN(endTime) || startTime >= endTime) {
    return { status: 'needs_clarification', answer: null, success_indicators: { question: 'window_start and window_end must be valid ISO dates with start < end.' }, trace };
  }

  // ---------- Helper: Tool Call with Retry ----------
  async function callWithRetry(name, args) {
    const maxRetries = 2;
    let attempt = 0;
    while (attempt <= maxRetries) {
      try {
        const result = await tools.call(name, args);
        trace.push(`Tool ${name} succeeded on attempt ${attempt + 1}`);
        return result;
      } catch (e) {
        if (e.name === 'ToolError' && ['UPSTREAM_503', 'TIMEOUT'].includes(e.code)) {
          attempt++;
          trace.push(`Tool ${name} transient error (${e.code}) attempt ${attempt}`);
          if (attempt > maxRetries) throw e;
        } else {
          trace.push(`Tool ${name} failed: ${e.code || e.message}`);
          throw e;
        }
      }
    }
  }

  // ---------- Gather Profiles ----------
  const profiles = {};
  for (const person of participants) {
    try {
      const profile = await callWithRetry('get_person_profile', { person });
      // Validate profile
      if (!profile || typeof profile !== 'object') throw new Error('Invalid profile');
      if (typeof profile.timezone !== 'string') throw new Error('Missing timezone');
      if (typeof profile.utc_offset_minutes !== 'number') throw new Error('Missing utc_offset_minutes');
      if (!profile.working_hours || typeof profile.working_hours.start !== 'string' || typeof profile.working_hours.end !== 'string')
        throw new Error('Missing working_hours');
      profiles[person] = profile;
    } catch (e) {
      trace.push(`Failed to get profile for ${person}: ${e.message}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
  }

  // ---------- Helper: Convert UTC to Local Minutes ----------
  function utcToLocalMinutes(date, offsetMinutes) {
    return date.getUTCHours() * 60 + date.getUTCMinutes() + offsetMinutes;
  }

  // ---------- Helper: Convert Local Minutes to UTC Date ----------
  function localMinutesToUtc(date, offsetMinutes, localMinutes) {
    const utcMinutes = localMinutes - offsetMinutes;
    const utcHour = Math.floor(utcMinutes / 60);
    const utcMinute = utcMinutes % 60;
    const newDate = new Date(date);
    newDate.setUTCHours(utcHour, utcMinute, 0, 0);
    return newDate;
  }

  // ---------- Gather Busy Intervals ----------
  const busyMap = {}; // person -> array of {start, end}
  for (const person of participants) {
    try {
      const busyRes = await callWithRetry('get_calendar', { person, start: window_start, end: window_end });
      if (!busyRes || !Array.isArray(busyRes.busy)) throw new Error('Invalid busy data');
      const cleaned = busyRes.busy.map(ev => {
        const s = new Date(ev.start);
        const e = new Date(ev.end);
        if (isNaN(s) || isNaN(e)) throw new Error('Invalid interval');
        return { start: s, end: e };
      });
      busyMap[person] = cleaned;
    } catch (e) {
      trace.push(`Failed to get calendar for ${person}: ${e.message}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
  }

  // ---------- Generate Candidate Slots ----------
  const slotInterval = 30; // minutes
  const candidateSlots = [];
  for (let t = startTime; t < endTime; t = new Date(t.getTime() + slotInterval * 60000)) {
    if (t.getUTCHours() * 60 + t.getUTCMinutes() % slotInterval !== 0) continue; // ensure :00 or :30
    const slotEnd = new Date(t.getTime() + duration_minutes * 60000);
    if (slotEnd > endTime) break;
    candidateSlots.push({ start: new Date(t), end: new Date(slotEnd) });
  }

  // ---------- Check Availability ----------
  function isSlotFree(slot) {
    for (const person of participants) {
      const profile = profiles[person];
      const offset = profile.utc_offset_minutes;
      const localStart = utcToLocalMinutes(slot.start, offset);
      const localEnd = utcToLocalMinutes(slot.end, offset);
      const [workStart, workEnd] = profile.working_hours.start.split(':').map(Number);
      const [workEndH, workEndM] = profile.working_hours.end.split(':').map(Number);
      const workStartMin = workStart * 60 + workStart;
      const workEndMin = workEndH * 60 + workEndM;
      if (localStart < workStartMin || localEnd > workEndMin) return false;
      for (const ev of busyMap[person]) {
        if (slot.start < ev.end && slot.end > ev.start) return false;
      }
    }
    return true;
  }

  const availableSlot = candidateSlots.find(isSlotFree);

  if (!availableSlot) {
    return { status: 'infeasible', answer: null, success_indicators: {}, trace };
  }

  const resultAnswer = {
    start: availableSlot.start.toISOString().replace('.000', ''),
    end: availableSlot.end.toISOString().replace('.000', ''),
    participants
  };

  // ---------- Send Invite if Confirmed ----------
  if (context.confirmed) {
    try {
      const inviteRes = await callWithRetry('send_invite', {
        participants,
        start: resultAnswer.start,
        end: resultAnswer.end,
        title: title || ''
      });
      if (!inviteRes || inviteRes.status !== 'sent') throw new Error('Invite not sent');
      trace.push(`Invite sent: ${inviteRes.invite_id}`);
    } catch (e) {
      trace.push(`Failed to send invite: ${e.message}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
  }

  return { status: 'success', answer: resultAnswer, success_indicators: {}, trace };
}
