async function run(task, tools, context) {
  const { participants, duration_minutes, window_start, window_end } = task.inputs;
  const trace = [];

  if (!participants || !Array.isArray(participants) || participants.length === 0) {
    return {
      status: 'needs_clarification',
      answer: null,
      success_indicators: { question: 'Participants list is missing or empty.' },
      trace: ['Missing participants']
    };
  }

  const duration = duration_minutes || 30;
  const wStart = new Date(window_start);
  const wEnd = new Date(window_end);

  if (isNaN(wStart.getTime()) || isNaN(wEnd.getTime())) {
    return {
      status: 'infeasible',
      answer: null,
      success_indicators: {},
      trace: ['Invalid window start or end']
    };
  }

  async function callToolWithRetry(name, args) {
    let attempts = 0;
    while (attempts < 3) {
      try {
        attempts++;
        return await tools.call(name, args);
      } catch (err) {
        if (attempts >= 3) throw err;
        // Retry transient errors or any error up to 3 times
      }
    }
  }

  // 1. Fetch profiles for all participants
  const profiles = {};
  for (const person of participants) {
    try {
      const res = await callToolWithRetry('get_person_profile', { person });
      profiles[person] = res;
    } catch (err) {
      trace.push(`Failed to get profile for ${person}: ${err.message}`);
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: {},
        trace
      };
    }
  }

  // 2. Fetch calendar busy slots for all participants
  const calendarBusy = {};
  for (const person of participants) {
    try {
      const res = await callToolWithRetry('get_calendar', {
        person,
        start: window_start,
        end: window_end
      });
      calendarBusy[person] = res.busy || [];
    } catch (err) {
      trace.push(`Failed to get calendar for ${person}: ${err.message}`);
      return {
        status: 'failed_gracefully',
        answer: null,
        success_indicators: {},
        trace
      };
    }
  }

  // Helper to convert UTC date to local time components (hours, minutes, date string)
  function getLocalTimeComponents(date, utcOffsetMinutes) {
    const localMs = date.getTime() + utcOffsetMinutes * 60 * 1000;
    const localDate = new Date(localMs);
    const year = localDate.getUTCFullYear();
    const month = String(localDate.getUTCMonth() + 1).padStart(2, '0');
    const day = String(localDate.getUTCDate()).padStart(2, '0');
    const hours = localDate.getUTCHours();
    const minutes = localDate.getUTCMinutes();
    return {
      dateStr: `${year}-${month}-${day}`,
      totalMinutes: hours * 60 + minutes
    };
  }

  // Parse HH:mm to minutes from midnight
  function parseHHmm(hhmm) {
    const [h, m] = hhmm.split(':').map(Number);
    return h * 60 + m;
  }

  // Check if a UTC time slot [slotStart, slotEnd) is valid for all participants
  function isSlotValid(slotStart, slotEnd) {
    const slotStartMs = slotStart.getTime();
    const slotEndMs = slotEnd.getTime();

    for (const person of participants) {
      const profile = profiles[person];
      const offset = profile.utc_offset_minutes;
      const workStartMin = parseHHmm(profile.working_hours.start);
      const workEndMin = parseHHmm(profile.working_hours.end);

      // Check slot duration against working hours and lunch locally
      // Since a slot might span across local days, check both start and end or sample points.
      // For simplicity, let's check start and end local times, and every 30 mins in between.
      const step = 30 * 60 * 1000;
      for (let t = slotStartMs; t < slotEndMs; t += step) {
        const d = new Date(t);
        const local = getLocalTimeComponents(d, offset);

        // Check working hours
        if (local.totalMinutes < workStartMin || local.totalMinutes + duration > workEndMin) {
          return false;
        }

        // Check lunch break: 12:30 (750m) to 14:00 (840m)
        // Overlap if local.totalMinutes < 840 and local.totalMinutes + 30 > 750
        const lunchStart = 12 * 60 + 30; // 750
        const lunchEnd = 14 * 60; // 840
        const currentEndMin = local.totalMinutes + 30;
        if (Math.max(local.totalMinutes, lunchStart) < Math.min(currentEndMin, lunchEnd)) {
          return false;
        }
      }

      // Also check calendar busy intervals
      const busyList = calendarBusy[person];
      for (const b of busyList) {
        if (b.all_day) {
          // If all day, check if the local date matches the busy date
          const localSlot = getLocalTimeComponents(slotStart, offset);
          if (b.start === localSlot.dateStr) {
            return false;
          }
        } else {
          const bStart = new Date(b.start).getTime();
          const bEnd = new Date(b.end).getTime();
          // Overlap check: slotStart < bEnd and slotEnd > bStart
          if (slotStartMs < bEnd && slotEndMs > bStart) {
            return false;
          }
        }
      }
    }

    return true;
  }

  // Iterate through potential slots on :00 and :30 UTC within window
  // Align window_start to the next :00 or :30
  let current = new Date(wStart.getTime());
  const min = current.getUTCMinutes();
  if (min > 0 && min < 30) {
    current.setUTCMinutes(30, 0, 0);
  } else if (min > 30) {
    current.setUTCHours(current.getUTCHours() + 1, 0, 0, 0);
  } else {
    current.setUTCSeconds(0, 0);
  }

  const stepMs = 30 * 60 * 1000;
  const durationMs = duration * 60 * 1000;

  while (true) {
    const slotEnd = new Date(current.getTime() + durationMs);
    if (slotEnd.getTime() > wEnd.getTime()) {
      break;
    }

    if (isSlotValid(current, slotEnd)) {
      trace.push(`Found valid slot: ${current.toISOString()} to ${slotEnd.toISOString()}`);
      return {
        status: 'success',
        answer: {
          start: current.toISOString().replace('.000Z', 'Z'),
          end: slotEnd.toISOString().replace('.000Z', 'Z'),
          participants
        },
        success_indicators: {},
        trace
      };
    }

    current = new Date(current.getTime() + stepMs);
  }

  trace.push('No valid meeting slot found within window.');
  return {
    status: 'infeasible',
    answer: null,
    success_indicators: {},
    trace
  };
}
