async function run(task, tools, context) {
    const trace = [];
    const inputs = task.inputs || {};

    // 1. Validate inputs
    const participants = inputs.participants;
    const durationMinutes = inputs.duration_minutes;
    const windowStartStr = inputs.window_start;
    const windowEndStr = inputs.window_end;

    if (!Array.isArray(participants) || participants.length === 0) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Please provide a non-empty array of participants.' },
            trace: ['Missing or invalid participants input']
        };
    }

    if (typeof durationMinutes !== 'number' || durationMinutes <= 0 || isNaN(durationMinutes)) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Please provide a valid positive integer for duration_minutes.' },
            trace: ['Missing or invalid duration_minutes input']
        };
    }

    if (typeof windowStartStr !== 'string' || typeof windowEndStr !== 'string') {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'Please provide valid window_start and window_end UTC ISO strings.' },
            trace: ['Missing or invalid window boundaries']
        };
    }

    const windowStartDate = new Date(windowStartStr);
    const windowEndDate = new Date(windowEndStr);

    if (isNaN(windowStartDate.getTime()) || isNaN(windowEndDate.getTime())) {
        return {
            status: 'needs_clarification',
            answer: null,
            success_indicators: { question: 'window_start and window_end must be valid ISO date strings.' },
            trace: ['Invalid ISO date format for window']
        };
    }

    if (windowStartDate >= windowEndDate) {
        return {
            status: 'infeasible',
            answer: null,
            success_indicators: { reason: 'window_start must be before window_end' },
            trace: ['window_start is not before window_end']
        };
    }

    // Helper for tool calls with retry
    async function callToolWithRetry(name, args) {
        let attempts = 0;
        let lastError = null;
        while (attempts < 3) {
            try {
                attempts++;
                return await tools.call(name, args);
            } catch (err) {
                lastError = err;
                // If it's a ToolError and NOT a client error (like INVALID_ARGS, NOT_FOUND), we might retry
                if (err && err.name === 'ToolError') {
                    if (['INVALID_ARGS', 'NOT_FOUND'].includes(err.code)) {
                        throw err;
                    }
                }
                // Wait briefly in memory (no setTimeout, so just loop or proceed)
            }
        }
        throw lastError;
    }

    // 2. Fetch profiles for all participants
    const profiles = {};
    for (const p of participants) {
        try {
            trace.push(`Fetching profile for ${p}`);
            const res = await callToolWithRetry('get_person_profile', { person: p });
            if (!res || typeof res.timezone !== 'string' || typeof res.utc_offset_minutes !== 'number' || !res.working_hours) {
                return {
                    status: 'failed_gracefully',
                    answer: null,
                    success_indicators: { error: `Invalid profile structure for ${p}` },
                    trace
                };
            }
            profiles[p] = {
                timezone: res.timezone,
                utc_offset_minutes: Number(res.utc_offset_minutes),
                working_hours: {
                    start: res.working_hours.start, // e.g. "09:00"
                    end: res.working_hours.end     // e.g. "17:00"
                }
            };
        } catch (err) {
            return {
                status: 'failed_gracefully',
                answer: null,
                success_indicators: { error: `Failed to fetch profile for ${p}: ${err.message}` },
                trace
            };
        }
    }

    // 3. Fetch calendar busy slots for all participants
    const busyMap = {};
    for (const p of participants) {
        try {
            trace.push(`Fetching calendar for ${p}`);
            const res = await callToolWithRetry('get_calendar', {
                person: p,
                start: windowStartStr,
                end: windowEndStr
            });
            const busyList = Array.isArray(res?.busy) ? res.busy : [];
            busyMap[p] = busyList.map(b => {
                let bStart, bEnd;
                if (b.all_day) {
                    // All day events span local day. Convert start/end to UTC boundaries or handle carefully.
                    // Usually all_day gives date strings like "YYYY-MM-DD". Let's assume full day UTC if parsing fails or treat as 00:00 to 24:00 local, 
                    // but simplest is to treat all_day as covering the entire calendar day in UTC or offset. 
                    // Let's parse b.start and b.end as UTC or dates.
                    bStart = new Date(b.start + 'T00:00:00Z').getTime();
                    bEnd = new Date(b.end + 'T23:59:59Z').getTime();
                } else {
                    bStart = new Date(b.start).getTime();
                    bEnd = new Date(b.end).getTime();
                }
                return { start: isNaN(bStart) ? 0 : bStart, end: isNaN(bEnd) ? 0 : bEnd };
            }).filter(b => b.start < b.end);
        } catch (err) {
            return {
                status: 'failed_gracefully',
                answer: null,
                success_indicators: { error: `Failed to fetch calendar for ${p}: ${err.message}` },
                trace
            };
        }
    }

    // Helper: parse "HH:mm" to total minutes from midnight
    function parseMinutes(hhmm) {
        const parts = hhmm.split(':');
        return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
    }

    // Helper: check if a UTC instant (timestamp) falls within working hours for a profile, in their local time.
    // UTC time + offset = local time.
    // Local time in minutes from midnight = (utc_ms + offset_ms) % ms_per_day, etc.
    function isWithinWorkingHours(utcMs, profile) {
        const offsetMs = profile.utc_offset_minutes * 60 * 1000;
        const localMs = utcMs + offsetMs;
        // Find minutes from midnight in local time
        const msInDay = 24 * 60 * 60 * 1000;
        let localDayMs = localMs % msInDay;
        if (localDayMs < 0) localDayMs += msInDay;
        const localMinutes = Math.floor(localDayMs / (60 * 1000));

        const workStartM = parseMinutes(profile.working_hours.start);
        const workEndM = parseMinutes(profile.working_hours.end);

        return localMinutes >= workStartM && localMinutes <= workEndM;
    }

    // Check if the entire interval [slotStartMs, slotEndMs] is within working hours for a person
    // Since working hours are continuous blocks per local day, let's check sample points or ensure start and end and any day-boundary are valid.
    // Actually, checking every minute or checking start, end, and ensuring no overnight working hours violation is needed. 
    // Usually working hours are within the same local calendar day (e.g. 09:00 to 17:00).
    function isIntervalWithinWorkingHours(slotStartMs, slotEndMs, profile) {
        // We can check at the start, end, and every minute or check that local start/end fall in working hours 
        // AND do not cross working hour bounds/different local days if working hours don't span 24h.
        // Given typical working hours (e.g. 9 to 5), checking that both start and end are within working hours 
        // AND that local dates for start and end are the same (or valid working continuity) is robust enough.
        // Let's check start and end instants:
        if (!isWithinWorkingHours(slotStartMs, profile) || !isWithinWorkingHours(slotEndMs, profile)) {
            return false;
        }
        // Also check if local calendar day changes between start and end (meeting shouldn't cross midnight or leave working hours)
        const offsetMs = profile.utc_offset_minutes * 60 * 1000;
        const localStartDay = Math.floor((slotStartMs + offsetMs) / (24 * 60 * 60 * 1000));
        const localEndDay = Math.floor((slotEndMs + offsetMs) / (24 * 60 * 60 * 1000));
        if (localStartDay !== localEndDay) {
            return false;
        }
        return true;
    }

    // Check calendar conflicts for a person in [slotStartMs, slotEndMs]
    function hasConflict(p, slotStartMs, slotEndMs) {
        const busyList = busyMap[p] || [];
        for (const b of busyList) {
            // Overlap condition: start1 < end2 AND start2 < end1
            if (slotStartMs < b.end && b.start < slotEndMs) {
                return true;
            }
        }
        return false;
    }

    // 4. Generate candidate slots on :00 / :30 UTC within window
    // Slots are aligned to 30-minute marks (:00, :30).
    const slotDurationMs = durationMinutes * 60 * 1000;
    const stepMs = 30 * 60 * 1000; // 30 minutes step

    // Align windowStart to the nearest past or equal 30-min slot (:00 or :30)
    let currentMs = Math.ceil(windowStartDate.getTime() / stepMs) * stepMs;
    const endLimitMs = windowEndDate.getTime();

    let foundSlot = null;

    trace.push(`Scanning slots from ${new Date(currentMs).toISOString()} to ${windowEndDate.toISOString()} with duration ${durationMinutes}m`);

    while (currentMs + slotDurationMs <= endLimitMs) {
        const slotStartMs = currentMs;
        const slotEndMs = currentMs + slotDurationMs;

        // Check constraints for all participants
        let validSlot = true;
        for (const p of participants) {
            const profile = profiles[p];
            // 1. Working hours check
            if (!isIntervalWithinWorkingHours(slotStartMs, slotEndMs, profile)) {
                validSlot = false;
                break;
            }
            // 2. Conflict check
            if (hasConflict(p, slotStartMs, slotEndMs)) {
                validSlot = false;
                break;
            }
        }

        if (validSlot) {
            foundSlot = {
                start: new Date(slotStartMs).toISOString().replace(/\.\d{3}Z$/, 'Z'),
                end: new Date(slotEndMs).toISOString().replace(/\.\d{3}Z$/, 'Z')
            };
            break;
        }

        currentMs += stepMs;
    }

    if (!foundSlot) {
        return {
            status: 'infeasible',
            answer: null,
            success_indicators: { reason: 'No valid meeting slot found satisfying all constraints within the window.' },
            trace
        };
    }

    trace.push(`Found earliest slot: ${foundSlot.start} to ${foundSlot.end}`);

    // 5. If confirmed, send invite. Note: send_invite requires context.confirmed === true.
    if (context.confirmed) {
        try {
            trace.push('Sending calendar invite');
            await callToolWithRetry('send_invite', {
                participants: participants,
                start: foundSlot.start,
                end: foundSlot.end,
                title: 'Scheduled Meeting'
            });
        } catch (err) {
            return {
                status: 'failed_gracefully',
                answer: null,
                success_indicators: { error: `Failed to send invite: ${err.message}` },
                trace
            };
        }
    } else {
        trace.push('User confirmation not present; invite not sent, returning successful slot finding.');
    }

    return {
        status: 'success',
        answer: {
            start: foundSlot.start,
            end: foundSlot.end,
            participants: participants
        },
        success_indicators: { scheduled: true, confirmed: context.confirmed },
        trace
    };
}
