async function run(task, tools, context) {
  const trace = [];
  const successIndicators = {};

  // ---------- Input validation ----------
  const { participants, duration_minutes, window_start, window_end } = task.inputs || {};

  // Helper to validate ISO UTC string
  const isValidISOUTC = (s) => {
    if (typeof s !== 'string') return false;
    const d = new Date(s);
    return !isNaN(d.getTime()) && s.endsWith('Z');
  };

  if (!Array.isArray(participants) || participants.length === 0) {
    successIndicators.question = 'participants must be a non-empty array of usernames';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (typeof duration_minutes !== 'number' || duration_minutes <= 0) {
    successIndicators.question = 'duration_minutes must be a positive integer';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (!isValidISOUTC(window_start)) {
    successIndicators.question = 'window_start must be a valid UTC ISO string ending with Z';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  if (!isValidISOUTC(window_end)) {
    successIndicators.question = 'window_end must be a valid UTC ISO string ending with Z';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }
  const winStart = new Date(window_start);
  const winEnd = new Date(window_end);
  if (winEnd <= winStart) {
    successIndicators.question = 'window_end must be after window_start';
    return { status: 'needs_clarification', answer: null, success_indicators: successIndicators, trace };
  }

  // ---------- Helper to call tools with retries ----------
  const callTool = async (name, args) => {
    const maxRetries = 2;
    let attempt = 0;
    while (attempt <= maxRetries) {
      try {
        const result = await tools.call(name, args);
        trace.push(`Tool ${name} succeeded`);
        return result;
      } catch (err) {
        if (err.name === 'ToolError' && ['UPSTREAM_503', 'TIMEOUT'].includes(err.code)) {
          attempt++;
          if (attempt > maxRetries) {
            trace.push(`Tool ${name} failed after retries: ${err.code}`);
            throw err;
          }
          trace.push(`Transient error on ${name}: ${err.code}. Retrying (${attempt})`);
        } else {
          trace.push(`Tool ${name} failed: ${err.code || err.message}`);
          throw err;
        }
      }
    }
  };

  // ---------- Fetch profiles ----------
  const profiles = {};
  for (const person of participants) {
    const profile = await callTool('get_person_profile', { person });
    // Validate profile
    if (!profile || typeof profile !== 'object' || profile.person !== person) {
      trace.push(`Invalid profile data for ${person}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
    if (!profile.timezone || typeof profile.timezone !== 'string') {
      trace.push(`Missing timezone for ${person}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
    if (typeof profile.utc_offset_minutes !== 'number') {
      trace.push(`Missing utc_offset_minutes for ${person}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
    if (!profile.working_hours || typeof profile.working_hours.start !== 'string' || typeof profile.working_hours.end !== 'string') {
      trace.push(`Missing working_hours for ${person}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
    profiles[person] = profile;
  }

  // ---------- Fetch calendars ----------
  const busyIntervals = {};
  for (const person of participants) {
    const cal = await callTool('get_calendar', { person, start: window_start, end: window_end });
    if (!cal || typeof cal !== 'object' || cal.person !== person || !Array.isArray(cal.busy)) {
      trace.push(`Invalid calendar data for ${person}`);
      return { status: 'failed_gracefully', answer: null, success_indicators: {}, trace };
    }
    // Validate each busy interval
    const intervals = [];
    for (const ev of cal.busy) {
      if (!ev || typeof ev !== 'object') continue;
      const { start, end, all_day } = ev;
      if (!isValidISOUTC(start) || !isValidISOUTC(end)) continue;
      if (new Date(start) >= new Date(end)) continue;
      intervals.push({ start: new Date(start), end: new Date(end), all_day: !!all_day });
    }
    busyIntervals[person] = intervals;
  }

  // ---------- Helper to generate candidate slots ----------
  const msPerHalfHour = 30 * 60 * 1000;
  const msPerMinute = 60 * 1000;
  const durationMs = duration_minutes * msPerMinute;

  // Function to check if a time slot is within a person's working hours
  const isWithinWorkingHours = (person, slotStart) => {
    const profile = profiles[person];
    const localStart = new Date(slotStart.getTime() + profile.utc_offset_minutes * 60000);
    const hh = localStart.getHours().toString().padStart(2, '0');
    const mm = localStart.getMinutes().toString().padStart(2, '0');
    const localTime = `${hh}:${mm}`;
    const [workStartH, workStartM] = profile.working_hours.start.split(':').map(Number);
    const [workEndH, workEndM] = profile.working_hours.end.split(':').map(Number);
    const workStart = workStartH * 60 + workStartM;
    const workEnd = workEndH * 60 + workEndM;
    const slotLocalMin = localStart.getHours() * 60 + localStart.getMinutes();
    return slotLocalMin >= workStart && (slotLocalMin + duration_minutes) <= workEnd;
  };

  // Function to check lunch break
  const isDuringLunch = (person, slotStart) => {
    const profile = profiles[person];
    const localStart = new Date(slotStart.getTime() + profile.utc_offset_minutes * 60000);
    const hh = localStart.getHours();
    const mm = localStart.getMinutes();
    const localMin = hh * 60 + mm;
    // Lunch 12:30-14:00 => 750-840
    return localMin >= 750 && localMin < 840;
  };

  // Function to check if slot collides with busy intervals
  const collidesBusy = (person, slotStart, slotEnd) => {
    for (const ev of busyIntervals[person]) {
      if (ev.all_day) {
        // All day events block entire day
        const evStart = new Date(ev.start);
        const evEnd = new Date(ev.end);
        if (slotStart < evEnd && slotEnd > evStart) return true;
      } else {
        const evStart = ev.start;
        const evEnd = ev.end;
        if (slotStart < evEnd && slotEnd > evStart) return true;
      }
    }
    return false;
  };

  // ---------- Iterate over candidate slots ----------
  let candidateStart = new Date(Math.ceil(winStart.getTime() / msPerHalfHour) * msPerHalfHour);
  while (candidateStart.getTime() + durationMs <= winEnd.getTime()) {
    const candidateEnd = new Date(candidateStart.getTime() + durationMs);
    let slotValid = true;

    for (const person of participants) {
      // Working hours
      if (!isWithinWorkingHours(person, candidateStart)) {
        slotValid = false;
        break;
      }
      // Lunch break
      if (isDuringLunch(person, candidateStart)) {
        slotValid = false;
        break;
      }
      // Busy intervals
      if (collidesBusy(person, candidateStart, candidateEnd)) {
        slotValid = false;
        break;
      }
    }

    if (slotValid) {
      const answer = {
        start: candidateStart.toISOString().replace(/\.\d{3}Z$/, 'Z'),
        end: candidateEnd.toISOString().replace(/\.\d{3}Z$/, 'Z'),
        participants: [...participants]
      };
      return { status: 'success', answer, success_indicators: {}, trace };
    }

    candidateStart = new Date(candidateStart.getTime() + msPerHalfHour);
  }

  // No slot found
  return { status: 'infeasible', answer: null, success_indicators: {}, trace };
}
